CREATE OR REPLACE FUNCTION public.acknowledge_kpi_first_mypage_access_v1(p_context_id uuid, p_idempotency_key text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_subject uuid := public.kpi_v249_current_subject(); v_context public.kpi_tutorial_mypage_ready_contexts%rowtype;
  v_fact public.kpi_tutorial_journey_facts%rowtype; v_ready jsonb;
begin
  if p_context_id is null or p_idempotency_key is null or p_idempotency_key !~ '^[A-Za-z0-9_.:-]{1,128}$' then
    raise exception 'Invalid My Page acknowledgement' using errcode='22023'; end if;
  select * into v_context from public.kpi_tutorial_mypage_ready_contexts where context_id=p_context_id for update;
  if not found or v_context.subject_id<>v_subject or v_context.expires_at<=clock_timestamp()
    or not (v_context.profile_ready and v_context.onboarding_ready and v_context.identity_leader_ready
      and v_context.guild_membership_resolved) then
    raise exception 'Invalid or expired My Page context' using errcode='42501'; end if;
  -- Re-run all four server checks; a stale context cannot become canonical.
  v_ready := public.issue_kpi_mypage_ready_context_v1(v_context.tutorial_version,'recheck:'||p_idempotency_key,v_context.source);
  select * into v_fact from public.kpi_tutorial_journey_facts
    where subject_id=v_subject and fact_type='FIRST_MYPAGE_ACCESS_CONFIRMED';
  if found then
    if v_fact.idempotency_key is distinct from p_idempotency_key or v_fact.context_id is distinct from p_context_id then
      -- Subject-level canonical first fact wins; a new client attempt returns it
      -- only when this context was already acknowledged to that fact.
      if v_context.acknowledged_at is null then raise exception 'Canonical first My Page fact already exists' using errcode='23505'; end if;
    end if;
    return v_fact.id;
  end if;
  insert into public.kpi_tutorial_journey_facts(subject_id,fact_type,source,idempotency_key,
    tutorial_version,context_id,metadata)
  values(v_subject,'FIRST_MYPAGE_ACCESS_CONFIRMED',v_context.source,p_idempotency_key,
    v_context.tutorial_version,p_context_id,'{}') returning * into v_fact;
  update public.kpi_tutorial_mypage_ready_contexts set acknowledged_at=clock_timestamp()
    where context_id=p_context_id and acknowledged_at is null;
  return v_fact.id;
end;
$function$

CREATE OR REPLACE FUNCTION public.activate_preopen_guild_power_season()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_season public.ranking_seasons%rowtype;
  v_job_id bigint;
begin
  select season.* into strict v_season
  from public.ranking_seasons season
  join public.ranking_guild_power_season_master master on master.season_id=season.id
  where master.event_key='PREOPEN_GUILD_POWER_2026'
  for update of season;
  perform pg_advisory_xact_lock(hashtextextended('PREOPEN_GUILD_POWER_2026',0));

  if v_season.status='CLOSED' then
    select jobid into v_job_id from cron.job
    where jobname='preopen-guild-power-activate-20260904-jst';
    if v_job_id is not null then perform cron.unschedule(v_job_id); end if;
    return jsonb_build_object('season_id',v_season.id,'status','ALREADY_CLOSED');
  end if;
  if clock_timestamp()<v_season.starts_at then
    return jsonb_build_object('season_id',v_season.id,'status','NOT_STARTED');
  end if;

  -- Only the start-boundary authority may supersede the generic active season.
  update public.ranking_seasons
  set status='CLOSED',updated_at=clock_timestamp()
  where ranking_type='GUILD_POWER' and status='ACTIVE' and id<>v_season.id;
  update public.ranking_seasons
  set status=case when clock_timestamp()<ends_at then 'ACTIVE' else 'FINALIZING' end,
      updated_at=clock_timestamp()
  where id=v_season.id;

  select jobid into v_job_id from cron.job
  where jobname='preopen-guild-power-activate-20260904-jst';
  if v_job_id is not null then perform cron.unschedule(v_job_id); end if;
  return jsonb_build_object(
    'season_id',v_season.id,
    'status',case when clock_timestamp()<v_season.ends_at then 'ACTIVE' else 'FINALIZING' end
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.advance_ranking_season(p_type text, p_at timestamp with time zone DEFAULT clock_timestamp())
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_type text := upper(p_type);
  v_expired public.ranking_seasons%rowtype;
  v_start timestamptz;
  v_end timestamptz;
  v_current_id uuid;
begin
  if v_type not in ('PVP','RAID') then
    raise exception 'unsupported automatic ranking season type' using errcode='22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('ranking-season:'||v_type,0));

  select * into v_expired
  from public.ranking_seasons
  where ranking_type=v_type and status='ACTIVE' and ends_at<=p_at
  order by starts_at
  limit 1 for update;

  if found then
    update public.ranking_seasons set status='FINALIZING',updated_at=clock_timestamp()
    where id=v_expired.id;
    if v_type='PVP' then
      perform public.assert_pvp_boundary_replay_continuity(v_expired.id,p_at);
      perform public.finalize_pvp_season_rewards(v_expired.id);
      perform public.reconcile_pvp_after_season_boundary(v_expired.id,p_at);
    else
      perform public.finalize_raid_season_rewards(v_expired.id);
    end if;
    update public.ranking_seasons set status='CLOSED',updated_at=clock_timestamp()
    where id=v_expired.id;
  end if;

  select season.id into v_current_id
  from public.ranking_seasons season
  where season.ranking_type=v_type and season.status='ACTIVE'
    and p_at>=season.starts_at and p_at<season.ends_at
  order by season.starts_at desc limit 1;
  if v_current_id is not null then return v_current_id; end if;

  select bounds.starts_at,bounds.ends_at into v_start,v_end
  from public.ranking_period_bounds(v_type,p_at) bounds;
  insert into public.ranking_seasons(ranking_type,starts_at,ends_at,status)
  values(v_type,v_start,v_end,'ACTIVE')
  on conflict(ranking_type,starts_at) do update set
    ends_at=excluded.ends_at,status='ACTIVE',updated_at=clock_timestamp()
  returning id into v_current_id;
  return v_current_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.apply_canonical_guild_exp(p_guild_id uuid, p_exp integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_level integer;v_xp integer;v_required integer;
begin
 if p_exp<0 then raise exception 'guild EXP cannot be negative'; end if;
 select level,xp into v_level,v_xp from public.guilds where id=p_guild_id and not is_disbanded for update;
 if not found then raise exception 'active guild not found'; end if;
 v_xp:=coalesce(v_xp,0)+p_exp;
 while v_level<5 loop
  select required_exp into v_required from public.canonical_guild_progression_master where level=v_level;
  exit when v_xp<v_required;
  v_xp:=v_xp-v_required; v_level:=v_level+1;
 end loop;
 update public.guilds set level=v_level,xp=v_xp where id=p_guild_id;
 return jsonb_build_object('level',v_level,'xp',v_xp,'memberCap',public.canonical_guild_member_cap(p_guild_id));
end $function$

CREATE OR REPLACE FUNCTION public.apply_tutorial_player_snapshot(p_user_id uuid, p_snapshot jsonb)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select case when exists(
    select 1 from public.tutorial_progress
    where user_id=p_user_id and step_id='TUTORIAL_BATTLE'
  ) then coalesce((
    select jsonb_agg(
      case when unit_ordinality=1 then jsonb_set(
        unit,'{skills}',coalesce((
          select jsonb_agg(
            jsonb_set(skill,'{initialCooldown}','2'::jsonb,true)
            order by skill_ordinality
          )
          from jsonb_array_elements(coalesce(unit->'skills','[]'::jsonb))
            with ordinality skills(skill,skill_ordinality)
        ),'[]'::jsonb),true
      ) else unit end
      order by unit_ordinality
    )
    from jsonb_array_elements(coalesce(p_snapshot,'[]'::jsonb))
      with ordinality units(unit,unit_ordinality)
  ),'[]'::jsonb) else p_snapshot end;
$function$

CREATE OR REPLACE FUNCTION public.apply_user_xp(p_user_id uuid, p_xp_amount integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_level integer; v_xp integer; v_required integer; v_leveled boolean:=false;
begin
 if p_xp_amount<0 then raise exception 'XP amount must not be negative' using errcode='22023'; end if;
 select level,xp into v_level,v_xp from public.users where id=p_user_id for update;
 if not found then raise exception 'user not found' using errcode='P0002'; end if;
 if v_level>100 then
  return jsonb_build_object('level',v_level,'xp',v_xp,'leveled_up',false,'level_cap',100,'over_cap_audit',true);
 end if;
 if v_level=100 then
  update public.users set xp=0 where id=p_user_id;
  return jsonb_build_object('level',100,'xp',0,'leveled_up',false,'level_cap',100);
 end if;
 v_xp:=greatest(coalesce(v_xp,0),0)+p_xp_amount;
 while v_level<100 loop
  select required_exp into v_required from public.canonical_user_level_master where version='2026-08-22' and level=v_level;
  exit when v_required is null or v_required=0 or v_xp<v_required;
  v_xp:=v_xp-v_required; v_level:=v_level+1; v_leveled:=true;
 end loop;
 if v_level=100 then v_xp:=0; end if;
 update public.users set level=v_level,xp=v_xp where id=p_user_id;
 return jsonb_build_object('level',v_level,'xp',v_xp,'leveled_up',v_leveled,'level_cap',100);
end $function$

CREATE OR REPLACE FUNCTION public.begin_kpi_acquisition_journey_v1(p_token text, p_source text DEFAULT 'web_v1'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_hash text; v_row public.kpi_acquisition_journeys%rowtype;
begin
  -- Token must be generated with a CSPRNG by the server/browser. Never logged by
  -- the future API. PostgreSQL/API query logging must redact RPC parameters.
  if p_token is null or p_token !~ '^[a-f0-9]{64}$' or p_source is null
     or p_source not in ('web_v1','server_v1','qa_v1')
     or (auth.jwt()->>'role' is distinct from 'service_role' and p_source<>'web_v1') then
    raise exception 'Invalid acquisition request' using errcode = '22023';
  end if;
  v_hash := encode(sha256(convert_to(p_token,'UTF8')),'hex');
  perform pg_advisory_xact_lock(hashtextextended('kpi249:journey:'||v_hash,0));
  select * into v_row from public.kpi_acquisition_journeys where journey_token_hash = v_hash;
  if found then
    if v_row.source is distinct from p_source then
      raise exception 'Conflicting journey retry' using errcode = '23505';
    end if;
    return v_row.journey_id;
  end if;
  insert into public.kpi_acquisition_journeys(journey_token_hash,source)
  values(v_hash,p_source) returning * into v_row;
  return v_row.journey_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.bind_kpi_acquisition_subject_v1(p_token text, p_source text DEFAULT 'web_v1'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_subject uuid := public.kpi_v249_current_subject(); v_journey uuid;
  v_row public.kpi_acquisition_subject_bindings%rowtype;
begin
  if p_token is null or p_token !~ '^[a-f0-9]{64}$' or p_source is null
     or p_source <> 'web_v1' then
    raise exception 'Invalid binding request' using errcode = '22023';
  end if;
  select journey_id into v_journey from public.kpi_acquisition_journeys
  where journey_token_hash = encode(sha256(convert_to(p_token,'UTF8')),'hex') for update;
  if v_journey is null then raise exception 'Unknown journey' using errcode = '42501'; end if;
  select * into v_row from public.kpi_acquisition_subject_bindings where journey_id = v_journey;
  if found then
    if v_row.subject_id is distinct from v_subject or v_row.source is distinct from p_source then
      raise exception 'Journey already bound with different payload' using errcode = '23505';
    end if;
    return v_row.subject_id;
  end if;
  insert into public.kpi_acquisition_subject_bindings(journey_id,subject_id,source)
  values(v_journey,v_subject,p_source);
  return v_subject;
end;
$function$

CREATE OR REPLACE FUNCTION public.build_server_battle_snapshot(p_user_id uuid, p_character_ids text[], p_team text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_base jsonb; v_result jsonb;
begin
  v_base := public.build_server_battle_snapshot_00168(p_user_id,p_character_ids,p_team);
  select jsonb_agg(
    jsonb_set(
      jsonb_set(unit.value || (projection.value-'_equipmentUtilityCorrection'),'{stats,spd}',
        to_jsonb((unit.value#>>'{stats,spd}')::integer+coalesce((projection.value#>>'{_equipmentUtilityCorrection,spd}')::integer,0))),
      '{stats,luk}',to_jsonb((unit.value#>>'{stats,luk}')::integer+coalesce((projection.value#>>'{_equipmentUtilityCorrection,luk}')::integer,0))
    ) order by unit.ordinality)
  into v_result
  from jsonb_array_elements(v_base) with ordinality unit(value,ordinality)
  cross join lateral (select public.canonical_equipment_runtime_projection(
    p_user_id,regexp_replace(unit.value->>'id','^[^_]+_','')::uuid
  ) value) projection;
  return coalesce(v_result,'[]'::jsonb);
end $function$

CREATE OR REPLACE FUNCTION public.canonical_equipment_runtime_projection_00170(p_user_id uuid, p_user_character_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_status_chance integer := 0;
  v_status_resist integer := 0;
  v_blind_resist integer := 0;
  v_silence_resist integer := 0;
  v_crit_rate integer := 0;
  v_crit_damage integer := 0;
  v_damage_dealt integer := 0;
  v_damage_reduction integer := 0;
  v_effects jsonb := '[]'::jsonb;
  v_match text[];
  v_record record;
  v_raw text;
begin
  for v_record in
    select master.category, master.fixed_effects, greatest(least(coalesce(owned.plus_val,0),10),0) plus_val
    from public.user_equipments owned
    join public.canonical_equipment_master master
      on master.version='2026-08-21'
     and master.equipment_id=coalesce(nullif(owned.equipment_id,''),owned.equipment_master_id)
    join public.user_characters character
      on character.id=p_user_character_id and character.user_id=p_user_id
    where owned.user_id=p_user_id
      and owned.equipped_character_id=p_user_character_id::text
      and (master.exclusive_character_id is null or master.exclusive_character_id=character.character_id)
  loop
    v_effects := v_effects || v_record.fixed_effects || public.canonical_equipment_lb_options(v_record.category,v_record.plus_val);
    for v_raw in select jsonb_array_elements_text(v_record.fixed_effects)
    loop
      if v_raw !~* 'First Skill' then
        v_match := regexp_match(v_raw,'Status Chance([0-9]+)%','i');
        if v_match is not null then v_status_chance := greatest(v_status_chance,v_match[1]::integer*100); end if;
      end if;
      if v_raw !~* 'First Status' then
        v_match := regexp_match(v_raw,'Status Resist([0-9]+)%','i');
        if v_match is not null then v_status_resist := greatest(v_status_resist,v_match[1]::integer*100); end if;
      end if;
      v_match := regexp_match(v_raw,'Blind Resist([0-9]+)%','i');
      if v_match is not null then v_blind_resist := greatest(v_blind_resist,v_match[1]::integer*100); end if;
      v_match := regexp_match(v_raw,'Silence Resist([0-9]+)%','i');
      if v_match is not null then v_silence_resist := greatest(v_silence_resist,v_match[1]::integer*100); end if;
      v_match := regexp_match(v_raw,'Crit Rate([0-9]+)%','i');
      if v_match is not null then v_crit_rate := greatest(v_crit_rate,v_match[1]::integer*100); end if;
      v_match := regexp_match(v_raw,'Crit Damage([0-9]+)%','i');
      if v_match is not null then v_crit_damage := greatest(v_crit_damage,v_match[1]::integer*100); end if;
      v_match := regexp_match(v_raw,'DR([0-9]+)%','i');
      if v_match is not null then v_damage_reduction := greatest(v_damage_reduction,v_match[1]::integer*100); end if;
    end loop;

    if v_record.category='HEAD' and v_record.plus_val>=5 then v_status_resist:=greatest(v_status_resist,800); end if;
    if v_record.category='HEAD' and v_record.plus_val>=10 then v_damage_reduction:=greatest(v_damage_reduction,600); end if;
    if v_record.category='BODY' and v_record.plus_val>=10 then v_damage_reduction:=greatest(v_damage_reduction,800); end if;
    if v_record.category='ACCESSORY' and v_record.plus_val>=5 then v_crit_rate:=greatest(v_crit_rate,500); end if;
    if v_record.category='ACCESSORY' and v_record.plus_val>=10 then v_crit_damage:=greatest(v_crit_damage,1000); end if;
    if v_record.category='WEAPON' and v_record.plus_val>=5 then v_crit_damage:=greatest(v_crit_damage,800); end if;
    if v_record.category='WEAPON' and v_record.plus_val>=10 then v_damage_dealt:=greatest(v_damage_dealt,800); end if;
  end loop;

  return jsonb_build_object(
    'statusModifiers',jsonb_build_object(
      'statusChanceGenericBp',v_status_chance,
      'statusChanceIndividualBp',jsonb_build_object('STUN',0,'SILENCE',0,'BLIND',0,'POISON',0,'BLEED',0,'TAUNT',0),
      'statusResistanceGenericBp',least(v_status_resist,4000),
      'statusResistanceIndividualBp',jsonb_build_object('STUN',0,'SILENCE',least(v_silence_resist,5000),'BLIND',least(v_blind_resist,5000),'POISON',0,'BLEED',0,'TAUNT',0)
    ),
    'combatModifiers',jsonb_build_object(
      'criticalRatePositiveBp',v_crit_rate,
      'criticalRateNegativeBp',0,
      'criticalDamageBp',v_crit_damage,
      'damageDealtPositiveBp',v_damage_dealt,
      'damageDealtNegativeBp',0,
      'damageReductionBp',least(v_damage_reduction,6000)
    ),
    'equipmentEffects',v_effects
  );
end $function$

CREATE OR REPLACE FUNCTION public.canonical_ranking_reward_payload()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_payload jsonb; v_daily jsonb;
begin
  select master.payload into v_payload
  from public.canonical_master_freeze_versions master
  where master.domain='RANKING_REWARD' and master.version='2026-09-03'
    and master.is_production_enabled;
  if v_payload is null then
    raise exception 'active canonical ranking reward master is missing' using errcode='P0002';
  end if;
  select jsonb_object_agg(grouped.ranking_type,grouped.rewards order by grouped.ranking_type)
  into v_daily
  from (
    select master.ranking_type,
      jsonb_agg(jsonb_build_array(master.rank_min,master.rank_max,master.item_id,master.quantity)
        order by master.rank_min,master.item_id) rewards
    from public.canonical_daily_ranking_reward_master master
    where master.version='2026-09-03' and master.is_production_enabled
    group by master.ranking_type
  ) grouped;
  return v_payload||jsonb_build_object('daily',coalesce(v_daily,'{}'::jsonb));
end;
$function$

CREATE OR REPLACE FUNCTION public.capture_current_lifetime_onboarding_grant(p_user_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_history public.gacha_execution_history%rowtype;
  v_history_count integer;
  v_results jsonb;
  v_guaranteed text;
  v_growth_level integer;
  v_formation jsonb;
  v_formation_count integer;
  v_leader text;
  v_leader_owned uuid;
  v_skill text;
begin
  if p_user_id is null or not exists(select 1 from public.users where id=p_user_id) then return false; end if;
  if exists(select 1 from public.user_lifetime_onboarding_grants where user_id=p_user_id) then return true; end if;

  select count(*) into v_history_count
  from public.gacha_execution_history h
  where h.user_id=p_user_id and h.status='COMPLETED'
    and coalesce((h.result_payload->>'tutorial')::boolean,false)
    and jsonb_array_length(coalesce(h.result_payload->'results','[]'::jsonb))=10;
  if v_history_count<>1 then return false; end if;

  select * into v_history from public.gacha_execution_history h
  where h.user_id=p_user_id and h.status='COMPLETED'
    and coalesce((h.result_payload->>'tutorial')::boolean,false)
    and jsonb_array_length(coalesce(h.result_payload->'results','[]'::jsonb))=10
  limit 1;
  v_results:=v_history.result_payload->'results';
  select result->>'character_id' into v_guaranteed
  from jsonb_array_elements(v_results) result
  where coalesce((result->>'tutorial_slot')::integer,0)=10
    and result->>'rarity'='SSR';
  if v_guaranteed is null then return false; end if;

  select id,level into v_leader_owned,v_growth_level
  from public.user_characters
  where user_id=p_user_id and character_id=v_guaranteed
  order by created_at,id limit 1;
  if v_leader_owned is null or coalesce(v_growth_level,0)<7 then return false; end if;

  select jsonb_agg(owned.character_id order by formation.slot),count(*)
    into v_formation,v_formation_count
  from public.user_main_formations formation
  join public.user_characters owned on owned.id=formation.user_character_id and owned.user_id=formation.user_id
  where formation.user_id=p_user_id;
  if v_formation_count<>5 then return false; end if;

  select favorite_character_id into v_leader from public.users where id=p_user_id;
  if v_leader is null or v_leader<>v_formation->>0 then return false; end if;
  select skill_card_id into v_skill from public.user_skills
  where user_id=p_user_id
    and (equipped_character_id=v_leader_owned::text or equipped_character_id=v_leader)
  order by slot_index nulls last,created_at,id limit 1;
  if v_skill is null then return false; end if;

  insert into public.user_lifetime_onboarding_grants(
    user_id,canonical_payload,source,source_reference,canonical_master_version,first_granted_at
  ) values (
    p_user_id,
    jsonb_build_object(
      'gacha_results',v_results,
      'guaranteed_ssr',v_guaranteed,
      'growth_target_character',v_guaranteed,
      'growth_target_level',7,
      'starter_skill',v_skill,
      'formation_character_ids',v_formation,
      'formation_order',jsonb_build_array(1,2,3,4,5),
      'leader_character',v_leader
    ),
    'TUTORIAL_CANONICAL_HISTORY',v_history.request_id,'2026-08-21',v_history.created_at
  ) on conflict(user_id) do nothing;
  return exists(select 1 from public.user_lifetime_onboarding_grants where user_id=p_user_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.capture_daily_ranking_guild_membership()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_day date:=(clock_timestamp() at time zone 'Asia/Tokyo')::date;
begin
  if tg_op='DELETE' then
    update public.ranking_daily_activity_snapshots set guild_id=null
    where ranking_day_key=v_day and user_id=old.user_id;
    return old;
  end if;
  if tg_op='UPDATE' and old.user_id is distinct from new.user_id then
    update public.ranking_daily_activity_snapshots set guild_id=null
    where ranking_day_key=v_day and user_id=old.user_id;
  end if;
  update public.ranking_daily_activity_snapshots set guild_id=new.guild_id
  where ranking_day_key=v_day and user_id=new.user_id;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.capture_daily_ranking_participation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_type text; v_day date;
begin
  if old.finalization_status='FINALIZED' or new.finalization_status<>'FINALIZED' then return new; end if;
  v_type:=case new.battle_mode when 'PVP' then 'PVP' when 'RAID' then 'RAID_PERSONAL' end;
  if v_type is null or new.finalized_at is null then return new; end if;
  v_day:=(new.finalized_at at time zone 'Asia/Tokyo')::date;
  insert into public.ranking_daily_participation(
    ranking_day_key,ranking_type,user_id,finalized_count,first_finalized_at,last_finalized_at
  ) values(v_day,v_type,new.requester_user_id,1,new.finalized_at,new.finalized_at)
  on conflict(ranking_day_key,ranking_type,user_id) do update set
    finalized_count=public.ranking_daily_participation.finalized_count+1,
    first_finalized_at=least(public.ranking_daily_participation.first_finalized_at,excluded.first_finalized_at),
    last_finalized_at=greatest(public.ranking_daily_participation.last_finalized_at,excluded.last_finalized_at);
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.capture_gvg_guild_result()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_season uuid; v_guild uuid;
begin
  if old.status<>'COMPLETED' and new.status='COMPLETED' then
    v_season:=public.current_ranking_season_id('GVG',coalesce(new.completed_at,clock_timestamp()));
    if v_season is not null then
      foreach v_guild in array array_remove(array[new.guild_a_id,new.guild_b_id],null) loop
        insert into public.gvg_guild_season_rankings(season_id,guild_id,rate,wins,losses)
        select v_season,v_guild,coalesce(rating.rating,1000),
          case when new.winner_guild_id=v_guild then 1 else 0 end,
          case when new.winner_guild_id is not null and new.winner_guild_id<>v_guild then 1 else 0 end
        from (select 1) seed left join public.gvg_guild_ratings rating on rating.guild_id=v_guild
        on conflict(season_id,guild_id) do update set
          rate=excluded.rate,wins=public.gvg_guild_season_rankings.wins+excluded.wins,
          losses=public.gvg_guild_season_rankings.losses+excluded.losses,updated_at=clock_timestamp();
      end loop;
    end if;
  end if;
  return new;
end;
$function$

