CREATE OR REPLACE FUNCTION public.capture_pvp_daily_win()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_delta integer;
begin
  if coalesce(current_setting('tribe_neon.ranking_reconcile',true),'')='on' then
    return new;
  end if;
  v_delta:=case when tg_op='INSERT' then greatest(coalesce(new.daily_wins,0),0)
                else greatest(coalesce(new.daily_wins,0)-coalesce(old.daily_wins,0),0) end;
  if v_delta>0 then
    insert into public.pvp_daily_wins(activity_date,user_id,wins,updated_at)
    values((clock_timestamp() at time zone 'Asia/Tokyo')::date,new.user_id,v_delta,clock_timestamp())
    on conflict(activity_date,user_id) do update set
      wins=public.pvp_daily_wins.wins+excluded.wins,updated_at=excluded.updated_at;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.claim_present(p_present_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_present public.presents%ROWTYPE;
BEGIN
  IF v_user_id IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  SELECT * INTO v_present
  FROM public.presents
  WHERE id = p_present_id
    AND user_id = v_user_id
    AND status = 'UNCLAIMED'
    AND (expire_at IS NULL OR expire_at > clock_timestamp())
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Present is not claimable'; END IF;

  PERFORM public.grant_present_payload(v_user_id, v_present.item_id, v_present.quantity);
  UPDATE public.presents
  SET status = 'CLAIMED', claimed_at = clock_timestamp()
  WHERE id = v_present.id;
  RETURN jsonb_build_object('status', 'success', 'present_id', v_present.id);
END;
$function$

CREATE OR REPLACE FUNCTION public.claim_present(p_user_id uuid, p_present_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_present public.presents%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL OR auth.uid() <> p_user_id THEN RAISE EXCEPTION 'not authorized'; END IF;
  SELECT * INTO v_present FROM public.presents WHERE id = p_present_id AND user_id = p_user_id AND status = 'UNCLAIMED' FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'present not found or already claimed'); END IF;
  IF v_present.item_id = 'CASH' THEN
    UPDATE public.users SET cash = cash + v_present.quantity WHERE id = p_user_id;
  ELSIF v_present.item_id IN ('DIA', 'DIAMOND') THEN
    UPDATE public.users SET neon_diamonds = neon_diamonds + v_present.quantity WHERE id = p_user_id;
  ELSIF v_present.item_id LIKE 'EQUIP_%' THEN
    INSERT INTO public.user_equipments (user_id, equipment_id, equipment_master_id, level, plus_val)
    VALUES (p_user_id, v_present.item_id, v_present.item_id, 1, 0);
  ELSE
    INSERT INTO public.user_items (user_id, item_id, quantity) VALUES (p_user_id, v_present.item_id, v_present.quantity)
    ON CONFLICT (user_id, item_id) DO UPDATE SET quantity = public.user_items.quantity + EXCLUDED.quantity;
  END IF;
  UPDATE public.presents SET status = 'CLAIMED', claimed_at = now() WHERE id = p_present_id;
  RETURN jsonb_build_object('status', 'success');
END;
$function$

CREATE OR REPLACE FUNCTION public.consume_tutorial_character_daily_free_gacha()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_today date := (clock_timestamp() at time zone 'Asia/Tokyo')::date;
  v_consumed integer := 0;
begin
  if new.gacha_id <> 'CHAR_NORMAL'
    or new.payment_source <> 'free'
    or new.pull_count <> 10
    or not exists (
      select 1
      from public.tutorial_progress progress
      where progress.user_id = new.user_id
        and progress.step_id = 'FREE_GACHA'
    ) then
    return new;
  end if;

  if exists (
    select 1
    from public.gacha_execution_history history
    where history.user_id = new.user_id
      and history.request_id = new.request_id
  ) then
    return new;
  end if;

  insert into public.user_daily_gacha_claims (
    user_id, gacha_type, last_claimed_date, updated_at
  ) values (
    new.user_id, 'CHARACTER', v_today, clock_timestamp()
  )
  on conflict (user_id, gacha_type) do update
  set last_claimed_date = excluded.last_claimed_date,
      updated_at = excluded.updated_at
  where public.user_daily_gacha_claims.last_claimed_date < excluded.last_claimed_date;

  get diagnostics v_consumed = row_count;
  if v_consumed <> 1 then
    raise exception 'daily free gacha already claimed' using errcode = '23505';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.converge_ranking_lifecycle_safety(p_at timestamp with time zone DEFAULT clock_timestamp())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_orphan record;
  v_active public.ranking_seasons%rowtype;
  v_previous public.ranking_seasons%rowtype;
  v_orphans integer := 0;
  v_cutovers integer := 0;
begin
  perform pg_advisory_xact_lock(hashtextextended('ranking-lifecycle-safety-convergence',0));

  -- A non-Preview clean chain may have run 00227 and then the schema-only path
  -- of 00228. Reconcile only the immediately superseded row left by that pair.
  for v_orphan in
    select distinct on (closed.ranking_type) closed.*
    from public.ranking_seasons closed
    join public.ranking_seasons active
      on active.ranking_type=closed.ranking_type and active.status='ACTIVE'
     and active.starts_at<closed.ends_at+interval '1 second'
     and active.ends_at>closed.ends_at
     and abs(extract(epoch from (active.created_at-closed.updated_at)))<300
    where closed.ranking_type in ('PVP','RAID') and closed.status='CLOSED'
      and closed.ends_at<=p_at
      and not exists(select 1 from public.ranking_season_transition_audits audit where audit.season_id=closed.id)
      and not exists(select 1 from public.ranking_pvp_season_snapshots snapshot where snapshot.season_id=closed.id)
      and not exists(select 1 from public.ranking_raid_personal_season_snapshots snapshot where snapshot.season_id=closed.id)
      and not exists(select 1 from public.ranking_raid_guild_season_snapshots snapshot where snapshot.season_id=closed.id)
      and not exists(select 1 from public.ranking_season_reward_grants grant_row where grant_row.season_id=closed.id)
    order by closed.ranking_type,closed.ends_at desc
  loop
    if v_orphan.ranking_type='PVP' then
      perform public.assert_pvp_boundary_replay_continuity(v_orphan.id,p_at);
      perform public.finalize_pvp_season_rewards(v_orphan.id);
      perform public.reconcile_pvp_after_season_boundary(v_orphan.id,p_at);
    else
      perform public.finalize_raid_season_rewards(v_orphan.id);
      insert into public.ranking_season_transition_audits(
        season_id,ranking_type,replay_count,post_boundary_user_count,
        before_projection,expected_projection,after_projection
      ) values(v_orphan.id,'RAID',0,0,'[]','[]','[]')
      on conflict(season_id) do nothing;
    end if;
    v_orphans:=v_orphans+1;
  end loop;

  select * into v_active from public.ranking_seasons
  where ranking_type='RAID' and status='ACTIVE' and p_at>=starts_at and p_at<ends_at
  order by starts_at desc limit 1 for update;
  if found then
    select * into v_previous from public.ranking_seasons
    where ranking_type='RAID' and status='CLOSED'
      and starts_at<v_active.starts_at and ends_at>v_active.starts_at and ends_at<v_active.ends_at
    order by ends_at desc limit 1 for update;
    if found then
      if exists(select 1 from public.raid_damage_logs log
          where log.created_at>=v_active.starts_at and log.created_at<v_previous.ends_at) then
        raise exception 'Raid cutover overlap contains damage logs' using errcode='23514';
      end if;
      if exists(select 1 from public.ranking_season_reward_grants grant_row where grant_row.season_id=v_active.id)
        or exists(select 1 from public.ranking_raid_personal_season_snapshots snapshot where snapshot.season_id=v_active.id)
        or exists(select 1 from public.ranking_raid_guild_season_snapshots snapshot where snapshot.season_id=v_active.id)
        or exists(select 1 from public.pvp_ranking_reward_grants grant_row where grant_row.season_id=v_active.id)
        or exists(select 1 from public.gvg_guild_season_rankings ranking where ranking.season_id=v_active.id)
        or exists(select 1 from public.gvg_individual_season_rankings ranking where ranking.season_id=v_active.id) then
        raise exception 'Raid cutover active season already has dependencies' using errcode='23514';
      end if;
      if exists(select 1 from public.ranking_seasons other
          where other.id<>v_active.id and other.ranking_type='RAID'
            and other.starts_at=v_previous.ends_at) then
        raise exception 'Raid cutover target boundary already exists' using errcode='23505';
      end if;
      update public.ranking_seasons set starts_at=v_previous.ends_at,updated_at=clock_timestamp()
      where id=v_active.id;
      v_cutovers:=v_cutovers+1;
    end if;
  end if;
  return jsonb_build_object('orphanSeasons',v_orphans,'raidCutovers',v_cutovers);
end;
$function$

CREATE OR REPLACE FUNCTION public.create_guild(p_user_id uuid, p_guild_name text, p_guild_description text, p_guild_logo text, p_guild_color text, p_creation_cost integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_cash INTEGER;
    v_new_guild_id UUID;
BEGIN
    SELECT cash INTO v_cash FROM public.users WHERE id = p_user_id;
    IF v_cash IS NULL OR v_cash < p_creation_cost THEN
        RETURN jsonb_build_object('error', 'キャッシュが不足しています。');
    END IF;

    INSERT INTO public.guilds (name, description, logo_icon, color_theme, level, xp, cash, approval_required, auto_kick_days)
    VALUES (p_guild_name, p_guild_description, COALESCE(p_guild_logo, 'guild_icon_default.png'), COALESCE(p_guild_color, 'red'), 1, 0, 0, false, 7)
    RETURNING id INTO v_new_guild_id;

    INSERT INTO public.guild_members (guild_id, user_id, role)
    VALUES (v_new_guild_id, p_user_id, 'MASTER');

    UPDATE public.users SET cash = cash - p_creation_cost, guild_id = v_new_guild_id WHERE id = p_user_id;

    PERFORM public.evaluate_mission_progress(p_user_id, 'GUILD_JOIN', 1);
    RETURN jsonb_build_object('guild_id', v_new_guild_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.create_guild_v2(p_user_id uuid, p_guild_name text, p_creation_cost integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_user public.users%rowtype; v_name text:=trim(coalesce(p_guild_name,'')); v_guild uuid;
begin
 if auth.uid() is null or auth.uid()<>p_user_id then raise exception 'Only the current user can create a guild' using errcode='42501'; end if;
 if char_length(v_name) not between 1 and 12 or p_creation_cost<>500 then raise exception 'Invalid guild creation request' using errcode='22023'; end if;
 perform pg_advisory_xact_lock(hashtextextended(auth.uid()::text||':guild-create',0));
 select * into v_user from public.users where id=auth.uid() for update;
 if not found or v_user.level<5 or v_user.cash<500 then raise exception 'Guild creation requirements are not met' using errcode='P0001'; end if;
 if v_user.guild_id is not null or exists(select 1 from public.guild_members where user_id=auth.uid()) then raise exception 'Leave the current guild before creating another guild' using errcode='23505'; end if;
 perform 1 from public.guilds where lower(trim(name))=lower(v_name) and not is_disbanded for update;
 if found then raise exception 'Guild name is already in use' using errcode='23505'; end if;
 update public.guild_join_requests set status='CANCELLED',reviewed_at=now(),reviewed_by=auth.uid() where user_id=auth.uid() and status='PENDING';
 insert into public.guilds(name,leader_id,level,xp,funds,recruitment_mode,approval_required) values(v_name,auth.uid(),1,0,0,'OPEN_JOIN',false) returning id into v_guild;
 insert into public.guild_members(guild_id,user_id,role,weekly_contribution,total_contribution) values(v_guild,auth.uid(),'MASTER',0,0);
 update public.users set cash=cash-500,guild_id=v_guild where id=auth.uid();
 perform public.evaluate_mission_progress(auth.uid(),'GUILD_JOIN',1);
 return jsonb_build_object('status','success','guild_id',v_guild,'cash_spent',500);
end $function$

CREATE OR REPLACE FUNCTION public.create_kpi_marketing_import_batch_v1(p_source text, p_actor_identifier uuid, p_file_hash text, p_idempotency_key text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_row public.kpi_marketing_import_batches%rowtype; v_admin boolean;
begin
  v_admin := auth.jwt()->>'role'='service_role' or coalesce(auth.jwt()->'app_metadata'->>'role','')='admin';
  if not v_admin or p_source not in ('x_ads_manager_manual','x_ads_manager_import')
    or p_actor_identifier is null or (p_file_hash is not null and p_file_hash !~ '^[a-f0-9]{64}$')
    or p_idempotency_key is null or p_idempotency_key !~ '^[A-Za-z0-9_.:-]{1,128}$'
    or not public.kpi_v249_metadata_valid(p_metadata)
    or (auth.jwt()->>'role'<>'service_role' and p_actor_identifier is distinct from auth.uid()) then
    raise exception 'Invalid marketing batch request' using errcode='42501'; end if;
  perform pg_advisory_xact_lock(hashtextextended('kpi249:marketing-batch:'||p_idempotency_key,0));
  select * into v_row from public.kpi_marketing_import_batches where idempotency_key=p_idempotency_key;
  if found then
    if v_row.source is distinct from p_source or v_row.actor_identifier is distinct from p_actor_identifier
      or v_row.file_hash is distinct from p_file_hash or v_row.metadata is distinct from p_metadata then
      raise exception 'Conflicting marketing batch retry' using errcode='23505'; end if;
    return v_row.id; end if;
  insert into public.kpi_marketing_import_batches(platform,source,actor_identifier,file_hash,idempotency_key,metadata)
  values('X',p_source,p_actor_identifier,p_file_hash,p_idempotency_key,p_metadata) returning * into v_row;
  return v_row.id;
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_canonical_guild_join_level()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_level integer;
begin
 select level into v_level from public.users where id=new.user_id;
 if coalesce(v_level,0)<3 then raise exception 'Guild joining requires user level 3' using errcode='42501'; end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.enforce_guild_member_cap()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_level INTEGER;
  v_cap INTEGER;
  v_count INTEGER;
BEGIN
  IF TG_OP <> 'INSERT' THEN RETURN NEW; END IF;
  SELECT level INTO v_level FROM public.guilds WHERE id = NEW.guild_id FOR UPDATE;
  IF v_level IS NULL THEN RAISE EXCEPTION 'Guild not found'; END IF;
  SELECT max_members INTO v_cap FROM public.guild_level_master WHERE level = v_level;
  v_cap := LEAST(COALESCE(v_cap, 10), 20);
  SELECT count(*) INTO v_count FROM public.guild_members WHERE guild_id = NEW.guild_id;
  IF v_count >= v_cap THEN RAISE EXCEPTION 'Guild member limit reached (% members)', v_cap; END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_kpi_classification_no_overlap()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if exists (
    select 1
    from public.kpi_account_classification_periods existing
    where existing.subject_id = new.subject_id
      and existing.id <> coalesce(new.id, -1)
      and tstzrange(existing.valid_from, coalesce(existing.valid_to, 'infinity'::timestamptz), '[)')
          && tstzrange(new.valid_from, coalesce(new.valid_to, 'infinity'::timestamptz), '[)')
  ) then
    raise exception 'KPI classification periods overlap' using errcode = '23P01';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_mission_claim_prerequisite()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_prerequisite text;
begin
  if new.status='CLAIMED' and old.status is distinct from 'CLAIMED' then
    select prerequisite_mission_id into v_prerequisite from public.missions where id=new.mission_id;
    if v_prerequisite is not null and not exists(
      select 1 from public.user_missions prerequisite
      where prerequisite.user_id=new.user_id and prerequisite.mission_id=v_prerequisite
        and prerequisite.status='CLAIMED'
    ) then raise exception 'mission prerequisite is not claimed' using errcode='23514'; end if;
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.finalize_daily_ranking_rewards(p_ranking_day_key date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_day date:=coalesce(p_ranking_day_key,(clock_timestamp() at time zone 'Asia/Tokyo')::date-1);
  v_today date:=(clock_timestamp() at time zone 'Asia/Tokyo')::date;
  v_start timestamptz; v_end timestamptz; v_row record;
  v_power integer:=0; v_guild integer:=0; v_pvp integer:=0; v_raid integer:=0;
begin
  if v_day>=v_today then raise exception 'daily ranking day is not closed' using errcode='22023'; end if;
  perform pg_advisory_xact_lock(hashtextextended('DAILY_RANKING:'||v_day::text,0));
  if exists(select 1 from public.ranking_daily_finalization_audits audit where audit.ranking_day_key=v_day) then
    return (select jsonb_build_object('ranking_day_key',audit.ranking_day_key,'status','ALREADY_FINALIZED',
      'POWER',audit.power_recipients,'GUILD_POWER',audit.guild_recipients,
      'PVP',audit.pvp_recipients,'RAID_PERSONAL',audit.raid_recipients)
      from public.ranking_daily_finalization_audits audit where audit.ranking_day_key=v_day);
  end if;
  v_start:=v_day::timestamp at time zone 'Asia/Tokyo';
  v_end:=(v_day+1)::timestamp at time zone 'Asia/Tokyo';

  insert into public.ranking_daily_entity_snapshots(ranking_day_key,ranking_type,ranked_entity_id,score,rank_position)
  select v_day,'POWER',ranked.user_id,ranked.score,ranked.rank_position
  from (
    select activity.user_id,activity.total_power score,
      row_number() over(order by activity.total_power desc,activity.user_id)::integer rank_position
    from public.ranking_daily_activity_snapshots activity
    where activity.ranking_day_key=v_day
  ) ranked where ranked.rank_position<=100;
  insert into public.ranking_daily_recipient_snapshots
  select snapshot.ranking_day_key,snapshot.ranking_type,snapshot.ranked_entity_id,
    snapshot.ranked_entity_id,snapshot.rank_position,snapshot.score
  from public.ranking_daily_entity_snapshots snapshot
  where snapshot.ranking_day_key=v_day and snapshot.ranking_type='POWER';

  with active_members as (
    select activity.guild_id,activity.user_id,activity.total_power member_power
    from public.ranking_daily_activity_snapshots activity
    where activity.ranking_day_key=v_day and activity.guild_id is not null
  ), ranked as (
    select member.guild_id,sum(member.member_power)::bigint score,
      row_number() over(order by sum(member.member_power) desc,member.guild_id)::integer rank_position
    from active_members member group by member.guild_id
  )
  insert into public.ranking_daily_entity_snapshots(ranking_day_key,ranking_type,ranked_entity_id,score,rank_position)
  select v_day,'GUILD_POWER',ranked.guild_id,ranked.score,ranked.rank_position
  from ranked where ranked.rank_position<=100;
  insert into public.ranking_daily_recipient_snapshots
  select snapshot.ranking_day_key,snapshot.ranking_type,snapshot.ranked_entity_id,
    member.user_id,snapshot.rank_position,snapshot.score
  from public.ranking_daily_entity_snapshots snapshot
  join public.ranking_daily_activity_snapshots member
    on member.ranking_day_key=snapshot.ranking_day_key
   and member.guild_id=snapshot.ranked_entity_id
  where snapshot.ranking_day_key=v_day and snapshot.ranking_type='GUILD_POWER'
    and member.guild_id is not null;

  insert into public.ranking_daily_entity_snapshots(ranking_day_key,ranking_type,ranked_entity_id,score,rank_position)
  select v_day,'PVP',ranked.user_id,ranked.score,ranked.rank_position
  from (
    select participation.user_id,coalesce(wins.wins,0)::bigint score,
      row_number() over(order by coalesce(wins.wins,0) desc,participation.first_finalized_at,participation.user_id)::integer rank_position
    from public.ranking_daily_participation participation
    left join public.pvp_daily_wins wins on wins.activity_date=v_day and wins.user_id=participation.user_id
    where participation.ranking_day_key=v_day and participation.ranking_type='PVP'
      and participation.finalized_count>=1
  ) ranked where ranked.rank_position<=100;
  insert into public.ranking_daily_recipient_snapshots
  select snapshot.ranking_day_key,snapshot.ranking_type,snapshot.ranked_entity_id,
    snapshot.ranked_entity_id,snapshot.rank_position,snapshot.score
  from public.ranking_daily_entity_snapshots snapshot
  where snapshot.ranking_day_key=v_day and snapshot.ranking_type='PVP';

  insert into public.ranking_daily_entity_snapshots(ranking_day_key,ranking_type,ranked_entity_id,score,rank_position)
  select v_day,'RAID_PERSONAL',ranked.user_id,ranked.score,ranked.rank_position
  from (
    select participation.user_id,coalesce(sum(log.raw_damage),0)::bigint score,
      row_number() over(order by coalesce(sum(log.raw_damage),0) desc,
        participation.first_finalized_at,participation.user_id)::integer rank_position
    from public.ranking_daily_participation participation
    join public.raid_damage_logs log on log.user_id=participation.user_id
      and log.created_at>=v_start and log.created_at<v_end
    where participation.ranking_day_key=v_day and participation.ranking_type='RAID_PERSONAL'
      and participation.finalized_count>=1
    group by participation.user_id,participation.first_finalized_at
  ) ranked where ranked.rank_position<=100;
  insert into public.ranking_daily_recipient_snapshots
  select snapshot.ranking_day_key,snapshot.ranking_type,snapshot.ranked_entity_id,
    snapshot.ranked_entity_id,snapshot.rank_position,snapshot.score
  from public.ranking_daily_entity_snapshots snapshot
  where snapshot.ranking_day_key=v_day and snapshot.ranking_type='RAID_PERSONAL';

  for v_row in
    select * from public.ranking_daily_recipient_snapshots recipient
    where recipient.ranking_day_key=v_day
    order by recipient.ranking_type,recipient.rank_position,recipient.recipient_user_id
  loop
    perform public.grant_canonical_daily_ranking_reward(v_day,v_row.ranking_type,
      v_row.recipient_user_id,v_row.ranked_entity_id,v_row.rank_position,v_row.score);
  end loop;
  select count(*) filter(where ranking_type='POWER'),count(*) filter(where ranking_type='GUILD_POWER'),
    count(*) filter(where ranking_type='PVP'),count(*) filter(where ranking_type='RAID_PERSONAL')
  into v_power,v_guild,v_pvp,v_raid
  from public.ranking_daily_reward_awards where ranking_day_key=v_day;
  insert into public.ranking_daily_finalization_audits(
    ranking_day_key,power_recipients,guild_recipients,pvp_recipients,raid_recipients
  ) values(v_day,v_power,v_guild,v_pvp,v_raid);
  return jsonb_build_object('ranking_day_key',v_day,'status','FINALIZED','POWER',v_power,
    'GUILD_POWER',v_guild,'PVP',v_pvp,'RAID_PERSONAL',v_raid);
end;
$function$

CREATE OR REPLACE FUNCTION public.finalize_expired_raid_instance(p_instance_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_instance public.raid_bosses%rowtype; v_user record;
begin
 select * into v_instance from public.raid_bosses where id=p_instance_id for update;
 if not found or v_instance.outcome_finalized_at is not null then return; end if;
 if v_instance.status='ACTIVE' and v_instance.current_hp>0 and v_instance.expires_at>clock_timestamp() then return; end if;
 if v_instance.current_hp=0 then
  update public.raid_bosses set status='CLEARED',outcome='DEFEAT_SUCCESS',outcome_finalized_at=now(),cleared_at=now(),respawn_after=now()+interval '5 minutes',raid_day_key=coalesce(raid_day_key,rotation_date::text) where id=p_instance_id returning * into v_instance;
  for v_user in select user_id from public.raid_instance_user_progress where raid_boss_instance_id=p_instance_id and finalized_battles>0 loop
   perform public.grant_canonical_raid_day_clear_reward(p_instance_id,v_user.user_id);
  end loop;
 else
  update public.raid_bosses set status='EXPIRED',outcome='TIMEOUT_FAILURE',outcome_finalized_at=now() where id=p_instance_id;
 end if;
end $function$

CREATE OR REPLACE FUNCTION public.finalize_preopen_guild_power_season()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_season public.ranking_seasons%rowtype;
  v_ranked_count integer;
  v_grant_count integer;
  v_job_id bigint;
begin
  -- All paths lock the season row before the event advisory lock. This avoids
  -- inversion with a transaction that edits season state then Power inputs.
  select season.* into strict v_season
  from public.ranking_seasons season
  join public.ranking_guild_power_season_master master on master.season_id=season.id
  where master.event_key='PREOPEN_GUILD_POWER_2026'
  for update of season;
  if v_season.status='PREPARING' and clock_timestamp()>=v_season.starts_at then
    perform public.activate_preopen_guild_power_season();
    select * into strict v_season from public.ranking_seasons where id=v_season.id;
  end if;
  perform pg_advisory_xact_lock(hashtextextended('PREOPEN_GUILD_POWER_2026',0));

  if clock_timestamp()<v_season.ends_at then
    raise exception 'pre-open guild Power season is not closed' using errcode='22023';
  end if;

  if exists(select 1 from public.ranking_guild_power_finalization_audits audit
            where audit.season_id=v_season.id) then
    select jobid into v_job_id from cron.job
    where jobname='preopen-guild-power-finalize-20260909-jst';
    if v_job_id is not null then perform cron.unschedule(v_job_id); end if;
    return (select jsonb_build_object(
      'season_id',audit.season_id,'status','ALREADY_FINALIZED',
      'ranked_guild_count',audit.ranked_guild_count,
      'reward_grant_count',audit.reward_grant_count)
      from public.ranking_guild_power_finalization_audits audit
      where audit.season_id=v_season.id);
  end if;

  update public.ranking_seasons set status='FINALIZING',updated_at=clock_timestamp()
  where id=v_season.id and status<>'CLOSED';

  insert into public.ranking_guild_power_season_snapshots(
    season_id,guild_id,guild_name,total_power,member_count,rank_position
  )
  with totals as (
    select guild.id guild_id,guild.name guild_name,
      sum(public.calculate_user_total_power(member.user_id))::bigint total_power,
      count(*)::integer member_count
    from public.guilds guild
    join public.guild_members member on member.guild_id=guild.id
    where not exists(
      select 1 from public.ranking_guild_exclusions exclusion where exclusion.guild_id=guild.id
    )
    group by guild.id,guild.name
    having sum(public.calculate_user_total_power(member.user_id))>0
  ), ranked as (
    select totals.*,rank() over(order by totals.total_power desc)::integer rank_position
    from totals
  )
  select v_season.id,ranked.guild_id,ranked.guild_name,ranked.total_power,
    ranked.member_count,ranked.rank_position
  from ranked
  on conflict(season_id,guild_id) do nothing;

  insert into public.ranking_guild_power_reward_grants(
    season_id,guild_id,cosmetic_id,rank_position
  )
  select snapshot.season_id,snapshot.guild_id,reward.cosmetic_id,snapshot.rank_position
  from public.ranking_guild_power_season_snapshots snapshot
  cross join lateral (
    values ('guild_preopen_2026_participation'::text),
      (case snapshot.rank_position
        when 1 then 'guild_preopen_2026_rank_1'
        when 2 then 'guild_preopen_2026_rank_2'
        when 3 then 'guild_preopen_2026_rank_3'
        else null end)
  ) reward(cosmetic_id)
  where snapshot.season_id=v_season.id and reward.cosmetic_id is not null
  on conflict(season_id,guild_id,cosmetic_id) do nothing;

  insert into public.guild_cosmetics(
    guild_id,cosmetic_id,source_type,source_reference
  )
  select grant_row.guild_id,grant_row.cosmetic_id,'RANKING',
    concat('PREOPEN_GUILD_POWER_2026:',grant_row.season_id)
  from public.ranking_guild_power_reward_grants grant_row
  where grant_row.season_id=v_season.id
  on conflict(guild_id,cosmetic_id) do nothing;

  insert into public.ranking_guild_power_reward_recipients(
    season_id,guild_id,recipient_user_id
  )
  select snapshot.season_id,snapshot.guild_id,member.user_id
  from public.ranking_guild_power_season_snapshots snapshot
  join public.guild_members member on member.guild_id=snapshot.guild_id
  where snapshot.season_id=v_season.id
  on conflict(season_id,guild_id,recipient_user_id) do nothing;

  insert into public.ranking_reward_notifications(
    recipient_user_id,period_kind,period_key,awarded_at,acknowledged_at
  )
  select recipient.recipient_user_id,'SEASON',recipient.season_id::text,clock_timestamp(),null
  from public.ranking_guild_power_reward_recipients recipient
  where recipient.season_id=v_season.id
  on conflict(recipient_user_id,period_kind,period_key) do update set
    awarded_at=excluded.awarded_at,acknowledged_at=null;

  select count(*) into v_ranked_count
  from public.ranking_guild_power_season_snapshots where season_id=v_season.id;
  select count(*) into v_grant_count
  from public.ranking_guild_power_reward_grants where season_id=v_season.id;

  update public.ranking_seasons set status='CLOSED',updated_at=clock_timestamp()
  where id=v_season.id;
  insert into public.ranking_guild_power_finalization_audits(
    season_id,ranked_guild_count,reward_grant_count
  ) values(v_season.id,v_ranked_count,v_grant_count);

  select jobid into v_job_id from cron.job
  where jobname='preopen-guild-power-finalize-20260909-jst';
  if v_job_id is not null then perform cron.unschedule(v_job_id); end if;

  return jsonb_build_object(
    'season_id',v_season.id,'status','FINALIZED',
    'ranked_guild_count',v_ranked_count,'reward_grant_count',v_grant_count
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.finalize_pvp_season_rewards(p_season_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_season public.ranking_seasons%rowtype;
  v_row record;
  v_granted integer := 0;
begin
  select * into v_season from public.ranking_seasons where id=p_season_id for update;
  if not found or v_season.ranking_type<>'PVP'
     or not (v_season.status in ('FINALIZING','CLOSED')
       or (v_season.status='ACTIVE' and v_season.ends_at<=clock_timestamp())) then
    raise exception 'PvP season is not finalizable' using errcode='23514';
  end if;

  insert into public.ranking_pvp_season_snapshots(
    season_id,user_id,rank_points,daily_wins,season_wins,rank_position,achieved_at
  )
  select p_season_id,ranked.user_id,ranked.boundary_rating,ranked.boundary_daily_wins,
    ranked.boundary_season_wins,ranked.rank_position,ranked.achieved_at
  from (
    select boundary.*,
      rank() over(order by boundary.boundary_rating desc) rank_position
    from (
      select rank.user_id,
        coalesce(first_event.new_rank-first_event.rank_delta,rank.rank_points) boundary_rating,
        rank.daily_wins-coalesce(post_events.win_count,0) boundary_daily_wins,
        rank.season_wins-coalesce(post_events.win_count,0) boundary_season_wins,
        case when first_event.user_id is null then rank.updated_at else v_season.ends_at end achieved_at
      from public.pvp_ranks rank
      left join lateral (
        select replay.requester_user_id user_id,
          (replay.finalization_result->>'newRankPoints')::integer new_rank,
          (replay.finalization_result->>'rankDelta')::integer rank_delta
        from public.battle_replay_sessions replay
        where replay.requester_user_id=rank.user_id and replay.battle_mode='PVP'
          and replay.finalization_status='FINALIZED' and replay.finalized_at>=v_season.ends_at
        order by replay.finalized_at,replay.id limit 1
      ) first_event on true
      left join lateral (
        select count(*) filter(where replay.finalization_result->>'winner'='PLAYER')::integer win_count
        from public.battle_replay_sessions replay
        where replay.requester_user_id=rank.user_id and replay.battle_mode='PVP'
          and replay.finalization_status='FINALIZED' and replay.finalized_at>=v_season.ends_at
      ) post_events on true
    ) boundary
  ) ranked
  on conflict do nothing;

  for v_row in
    select snapshot.* from public.ranking_pvp_season_snapshots snapshot
    where snapshot.season_id=p_season_id
    order by snapshot.rank_position,snapshot.achieved_at,snapshot.user_id
  loop
    v_granted := v_granted + public.grant_canonical_ranking_season_reward(
      p_season_id,'PVP',v_row.user_id,v_row.user_id,v_row.rank_position
    );
  end loop;
  return v_granted;
end;
$function$

CREATE OR REPLACE FUNCTION public.finalize_raid_battle(p_replay_id uuid, p_result jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_replay public.battle_replay_sessions%rowtype;
  v_instance public.raid_bosses%rowtype;
  v_raw bigint;
  v_applied bigint;
  v_remaining bigint;
  v_total bigint;
  v_progress public.raid_instance_user_progress%rowtype;
  v_final jsonb;
begin
  select * into v_replay
  from public.battle_replay_sessions
  where id = p_replay_id
  for update;

  if not found
     or v_replay.battle_mode <> 'RAID'
     or v_replay.resolution_authority <> 'RAID_SERVER' then
    raise exception 'not an official Raid replay' using errcode = '42501';
  end if;
  if v_replay.finalization_status = 'FINALIZED' then
    return v_replay.finalization_result;
  end if;
  if v_replay.status <> 'PENDING'
     or v_replay.finalization_status <> 'PENDING' then
    raise exception 'Raid replay is not finalizable' using errcode = '23514';
  end if;

  perform public.advance_ranking_season('RAID',clock_timestamp());
 perform public.validate_official_battle_result(p_result);
  select * into v_instance
  from public.raid_bosses
  where id = v_replay.source_reference_id
  for update;
  if not found or v_instance.raid_day_key is null or v_instance.raid_variant_id is null then
    raise exception 'Canonical Raid instance missing' using errcode = 'P0002';
  end if;

  v_raw := greatest(coalesce((p_result->>'playerRawDamage')::bigint, 0), 0);
  v_applied := least(v_raw, greatest(v_instance.current_hp, 0));
  v_remaining := greatest(v_instance.current_hp - v_applied, 0);

  update public.raid_bosses
  set current_hp = v_remaining
  where id = v_instance.id;

  insert into public.raid_damage_logs(
    boss_id, raid_boss_id, user_id, damage, damage_dealt,
    raid_boss_instance_id, battle_replay_session_id, guild_id,
    raw_damage, applied_damage
  ) values (
    v_instance.boss_id, v_instance.boss_id, v_replay.requester_user_id,
    v_raw, v_raw, v_instance.id, p_replay_id,
    nullif(v_replay.official_context->>'guildIdSnapshot', '')::uuid,
    v_raw, v_applied
  );

  insert into public.raid_instance_user_progress(
    raid_boss_instance_id, user_id, finalized_battles,
    raid_points_consumed, last_guild_id
  ) values (
    v_instance.id, v_replay.requester_user_id, 1,
    case when v_replay.official_context->>'costType' = 'RAID_POINT' then 1 else 0 end,
    nullif(v_replay.official_context->>'guildIdSnapshot', '')::uuid
  )
  on conflict(raid_boss_instance_id, user_id) do update set
    finalized_battles = public.raid_instance_user_progress.finalized_battles + 1,
    raid_points_consumed = public.raid_instance_user_progress.raid_points_consumed
      + excluded.raid_points_consumed,
    last_guild_id = excluded.last_guild_id,
    updated_at = clock_timestamp()
  returning * into v_progress;

  select coalesce(sum(raw_damage), 0) into v_total
  from public.raid_damage_logs
  where raid_boss_instance_id = v_instance.id
    and user_id = v_replay.requester_user_id;

  v_final := p_result || jsonb_build_object(
    'mode', 'RAID',
    'raidInstanceId', v_instance.id,
    'baseId', v_instance.base_id,
    'raidDayKey', v_instance.raid_day_key,
    'raidVariantId', v_instance.raid_variant_id,
    'rawDamage', v_raw,
    'appliedDamage', v_applied,
    'remainingBossHp', v_remaining,
    'personalContribution', v_total,
    'guildIdSnapshot', v_replay.official_context->>'guildIdSnapshot',
    'participationProgress', to_jsonb(v_progress)
  );

  insert into public.battle_replay_events(
    battle_replay_session_id, event_index, round_number, event_type, payload
  )
  select p_replay_id,
         greatest(coalesce((event.value->>'index')::integer, event.ordinality::integer - 1), 0),
         greatest(coalesce((event.value->>'round')::integer, 1), 1),
         coalesce(nullif(event.value->>'type', ''), 'UNKNOWN'),
         coalesce(event.value->'payload', '{}'::jsonb)
  from jsonb_array_elements(p_result->'events') with ordinality event(value, ordinality)
  on conflict do nothing;

  update public.battle_replay_sessions
  set status = 'RESOLVED',
      result = v_final,
      resolved_at = clock_timestamp(),
      finalization_status = 'FINALIZED',
      finalized_at = clock_timestamp(),
      finalization_result = v_final
  where id = p_replay_id;

  perform public.evaluate_mission_progress(
    v_replay.requester_user_id,
    'RAID_FINALIZED_BATTLE_COUNT',
    1
  );

  if v_remaining = 0 then
    perform public.finalize_expired_raid_instance(v_instance.id);
  end if;
  return v_final;
end
$function$

CREATE OR REPLACE FUNCTION public.finalize_raid_season_rewards(p_season_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_season public.ranking_seasons%rowtype;
  v_row record;
  v_member record;
  v_granted integer := 0;
begin
  select * into v_season from public.ranking_seasons where id=p_season_id for update;
  if not found or v_season.ranking_type<>'RAID'
     or not (v_season.status in ('FINALIZING','CLOSED')
       or (v_season.status='ACTIVE' and v_season.ends_at<=clock_timestamp())) then
    raise exception 'Raid season is not finalizable' using errcode='23514';
  end if;

  insert into public.ranking_raid_personal_season_snapshots(
    season_id,user_id,contribution,rank_position,achieved_at
  )
  select p_season_id,ranked.user_id,ranked.contribution,ranked.rank_position,ranked.achieved_at
  from (
    select totals.*,
      rank() over(order by totals.contribution desc) rank_position
    from (
      select log.user_id,sum(log.raw_damage)::bigint contribution,min(log.created_at) achieved_at
      from public.raid_damage_logs log
      where log.raid_boss_instance_id is not null
        and log.created_at>=v_season.starts_at and log.created_at<v_season.ends_at
      group by log.user_id
    ) totals
  ) ranked
  on conflict do nothing;

  insert into public.ranking_raid_guild_season_snapshots(
    season_id,guild_id,contribution,rank_position,achieved_at
  )
  select p_season_id,ranked.guild_id,ranked.contribution,ranked.rank_position,ranked.achieved_at
  from (
    select totals.*,
      rank() over(order by totals.contribution desc) rank_position
    from (
      select log.guild_id,sum(log.raw_damage)::bigint contribution,min(log.created_at) achieved_at
      from public.raid_damage_logs log
      where log.raid_boss_instance_id is not null and log.guild_id is not null
        and log.created_at>=v_season.starts_at and log.created_at<v_season.ends_at
      group by log.guild_id
    ) totals
  ) ranked
  on conflict do nothing;

  for v_row in
    select snapshot.* from public.ranking_raid_personal_season_snapshots snapshot
    where snapshot.season_id=p_season_id
    order by snapshot.rank_position,snapshot.achieved_at,snapshot.user_id
  loop
    v_granted := v_granted + public.grant_canonical_ranking_season_reward(
      p_season_id,'RAID_PERSONAL',v_row.user_id,v_row.user_id,v_row.rank_position
    );
  end loop;

  for v_row in
    select snapshot.* from public.ranking_raid_guild_season_snapshots snapshot
    where snapshot.season_id=p_season_id
    order by snapshot.rank_position,snapshot.achieved_at,snapshot.guild_id
  loop
    -- The frozen master holds guild funds. Preserve the established authority:
    -- only users who contributed for this guild in this exact season receive it.
    for v_member in
      select distinct log.user_id
      from public.raid_damage_logs log
      where log.guild_id=v_row.guild_id
        and log.raid_boss_instance_id is not null
        and log.created_at>=v_season.starts_at and log.created_at<v_season.ends_at
    loop
      v_granted := v_granted + public.grant_canonical_ranking_season_reward(
        p_season_id,'RAID_GUILD',v_member.user_id,v_row.guild_id,v_row.rank_position
      );
    end loop;
  end loop;
  return v_granted;
end;
$function$

CREATE OR REPLACE FUNCTION public.get_active_ranking_seasons()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object('season_id',season.id,'ranking_type',season.ranking_type,'starts_at',season.starts_at,'ends_at',season.ends_at,'status',season.status) order by season.ranking_type)
    from public.ranking_seasons season where season.status='ACTIVE' and clock_timestamp()>=season.starts_at and clock_timestamp()<season.ends_at),'[]'::jsonb);
end;
$function$

CREATE OR REPLACE FUNCTION public.get_raid_rankings(p_instance_id uuid, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_uid uuid:=auth.uid(); v_day text;
begin
 if v_uid is null then raise exception 'authentication required' using errcode='42501'; end if; if p_limit not between 1 and 100 or p_offset not between 0 and 10000 then raise exception 'invalid pagination' using errcode='22023'; end if;
 select raid_day_key into v_day from public.raid_bosses where id=p_instance_id; if v_day is null then raise exception 'Raid day not found' using errcode='P0002'; end if;
 return jsonb_build_object(
 'individual',coalesce((with totals as(select log.user_id,u.username,sum(log.raw_damage)::bigint contribution,min(log.created_at) achieved_at from public.raid_damage_logs log join public.raid_bosses boss on boss.id=log.raid_boss_instance_id and boss.raid_day_key=v_day join public.users u on u.id=log.user_id group by log.user_id,u.username),ranked as(select *,rank()over(order by contribution desc)rank_position from totals)select jsonb_agg(to_jsonb(page)order by contribution desc,achieved_at,user_id)from(select * from ranked order by contribution desc,achieved_at,user_id limit p_limit offset p_offset)page),'[]'::jsonb),
 'guild',coalesce((with totals as(select log.guild_id,g.name guild_name,sum(log.raw_damage)::bigint contribution,min(log.created_at) achieved_at,count(distinct log.user_id)::integer participant_count from public.raid_damage_logs log join public.raid_bosses boss on boss.id=log.raid_boss_instance_id and boss.raid_day_key=v_day join public.guilds g on g.id=log.guild_id where log.guild_id is not null group by log.guild_id,g.name),ranked as(select *,rank()over(order by contribution desc)rank_position from totals)select jsonb_agg(to_jsonb(page)order by contribution desc,achieved_at,guild_id)from(select * from ranked order by contribution desc,achieved_at,guild_id limit p_limit offset p_offset)page),'[]'::jsonb),
 'selfRank',(with totals as(select log.user_id,sum(log.raw_damage)::bigint contribution,min(log.created_at) achieved_at from public.raid_damage_logs log join public.raid_bosses boss on boss.id=log.raid_boss_instance_id and boss.raid_day_key=v_day group by log.user_id),ranked as(select *,rank()over(order by contribution desc)rank_position from totals)select to_jsonb(ranked)from ranked where user_id=v_uid));
end $function$

CREATE OR REPLACE FUNCTION public.grant_canonical_daily_ranking_reward(p_ranking_day_key date, p_ranking_type text, p_recipient_user_id uuid, p_ranked_entity_id uuid, p_rank_position integer, p_score bigint)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_award_id uuid; v_reward record; v_granted integer:=0; v_master_count integer;
begin
  if p_ranking_type not in ('POWER','GUILD_POWER','PVP','RAID_PERSONAL')
     or p_rank_position not between 1 and 100 then
    raise exception 'invalid daily ranking award' using errcode='22023';
  end if;
  select count(*) into v_master_count
  from public.canonical_daily_ranking_reward_master master
  where master.version='2026-09-03' and master.is_production_enabled
    and master.ranking_type=p_ranking_type
    and p_rank_position between master.rank_min and master.rank_max;
  if v_master_count<>2 then
    raise exception 'daily ranking reward master must resolve exactly two items' using errcode='23514';
  end if;

  insert into public.ranking_daily_reward_awards(
    ranking_day_key,ranking_type,recipient_user_id,ranked_entity_id,rank_position,score
  ) values(p_ranking_day_key,p_ranking_type,p_recipient_user_id,p_ranked_entity_id,p_rank_position,p_score)
  on conflict(ranking_day_key,ranking_type,recipient_user_id) do nothing
  returning id into v_award_id;
  if v_award_id is null then return 0; end if;

  for v_reward in
    select master.item_id,master.quantity
    from public.canonical_daily_ranking_reward_master master
    where master.version='2026-09-03' and master.is_production_enabled
      and master.ranking_type=p_ranking_type
      and p_rank_position between master.rank_min and master.rank_max
    order by master.item_id
  loop
    insert into public.ranking_daily_reward_item_grants(award_id,item_id,quantity)
    values(v_award_id,v_reward.item_id,v_reward.quantity);
    insert into public.user_items(user_id,item_id,quantity)
    values(p_recipient_user_id,v_reward.item_id,v_reward.quantity)
    on conflict(user_id,item_id) do update set
      quantity=public.user_items.quantity+excluded.quantity,updated_at=clock_timestamp();
    v_granted:=v_granted+1;
  end loop;

  insert into public.ranking_reward_notifications(
    recipient_user_id,period_kind,period_key,awarded_at,acknowledged_at
  ) values(p_recipient_user_id,'DAILY',p_ranking_day_key::text,clock_timestamp(),null)
  on conflict(recipient_user_id,period_kind,period_key) do update set
    awarded_at=excluded.awarded_at,acknowledged_at=null;
  return v_granted;
end;
$function$

CREATE OR REPLACE FUNCTION public.grant_canonical_guild_daily_exp(p_user_id uuid, p_source text, p_source_reference_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_guild uuid;v_exp integer;v_day date:=public.guild_jst_date();v_result jsonb;
begin
 select guild_id into v_guild from public.guild_members where user_id=p_user_id;
 if v_guild is null then return jsonb_build_object('status','not_in_guild'); end if;
 select exp_grant into v_exp from public.canonical_guild_exp_source_master where source=p_source and enabled and daily_per_member=1;
 if not found then raise exception 'unsupported Guild EXP source'; end if;
 insert into public.guild_exp_daily_ledger(guild_id,user_id,source,jst_date,exp_granted,source_reference_id)
 values(v_guild,p_user_id,p_source,v_day,v_exp,p_source_reference_id) on conflict(guild_id,user_id,source,jst_date) do nothing;
 if not found then return jsonb_build_object('status','already_recorded','source',p_source); end if;
 v_result:=public.apply_canonical_guild_exp(v_guild,v_exp);
 return jsonb_build_object('status','granted','source',p_source,'expGained',v_exp,'guild',v_result);
end $function$

CREATE OR REPLACE FUNCTION public.grant_canonical_raid_day_clear_reward(p_instance_id uuid, p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_instance public.raid_bosses%rowtype; v_claim public.raid_clear_reward_claims%rowtype; v_item record; v_inserted boolean; v_row_count integer;
begin
 select * into v_instance from public.raid_bosses where id=p_instance_id for update;
 if not found or v_instance.status<>'CLEARED' or v_instance.raid_day_key is null then return jsonb_build_object('eligible',false); end if;
 if not exists(select 1 from public.raid_instance_user_progress where raid_boss_instance_id=p_instance_id and user_id=p_user_id and finalized_battles>0) then return jsonb_build_object('eligible',false); end if;
 insert into public.raid_clear_reward_claims(raid_day_key,user_id,reward_type,source_instance_id)
 values(v_instance.raid_day_key,p_user_id,'CLEAR_REWARD',p_instance_id)
 on conflict do nothing; get diagnostics v_row_count=row_count; v_inserted:=v_row_count=1;
 select * into v_claim from public.raid_clear_reward_claims where raid_day_key=v_instance.raid_day_key and user_id=p_user_id and reward_type='CLEAR_REWARD' for update;
 if v_inserted then
  update public.raid_clear_reward_claims set ticket_roll=random()<0.30,ticket_item_id=public.resolve_canonical_reward_item('NORMAL_GACHA_TICKET_RANDOM'),awakening_roll=random()<0.01
  where raid_day_key=v_instance.raid_day_key and user_id=p_user_id and reward_type='CLEAR_REWARD' returning * into v_claim;
 end if;
 if not v_inserted and v_claim.delivery_status='DELIVERED' then return jsonb_build_object('eligible',true,'already_claimed',true); end if;
 begin
  for v_item in select * from (values('SKILL_MANUAL'::text,1,true),(v_claim.ticket_item_id,1,v_claim.ticket_roll),('AWAKENING_BOOK',1,v_claim.awakening_roll)) x(item_id,quantity,selected) where selected loop
   insert into public.raid_clear_reward_deliveries values(v_claim.raid_day_key,p_user_id,'CLEAR_REWARD',v_item.item_id,v_item.quantity,v_claim.source_instance_id,now()) on conflict do nothing;
   if found then insert into public.presents(user_id,item_id,quantity,message,status,expire_at) values(p_user_id,v_item.item_id,v_item.quantity,'レイドクリア報酬','UNCLAIMED',now()+interval '30 days'); end if;
  end loop;
  update public.raid_clear_reward_claims set delivery_status='DELIVERED',delivered_at=now(),last_error=null where raid_day_key=v_claim.raid_day_key and user_id=p_user_id and reward_type='CLEAR_REWARD';
 exception when others then
  update public.raid_clear_reward_claims set delivery_status='PENDING',last_error=sqlstate where raid_day_key=v_claim.raid_day_key and user_id=p_user_id and reward_type='CLEAR_REWARD';
 end;
 return jsonb_build_object('eligible',true,'already_claimed',not v_inserted,'ticket_roll',v_claim.ticket_roll,'awakening_roll',v_claim.awakening_roll);
end $function$

CREATE OR REPLACE FUNCTION public.grant_canonical_ranking_season_reward(p_season_id uuid, p_category text, p_recipient_user_id uuid, p_ranked_entity_id uuid, p_rank_position integer)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_entry record;
  v_reward_id text;
  v_item_id text;
  v_quantity integer;
  v_reward_key text;
  v_granted integer := 0;
  v_message text;
  v_present_id uuid;
begin
  if p_category not in ('PVP','RAID_PERSONAL','RAID_GUILD') then
    raise exception 'unsupported ranking reward category' using errcode='22023';
  end if;
  v_message := case p_category
    when 'PVP' then 'PvPシーズンランキング報酬'
    when 'RAID_PERSONAL' then 'レイド個人ランキング報酬'
    else 'レイドギルドランキング報酬'
  end;

  for v_entry in
    select entry.value,entry.ordinality
    from jsonb_array_elements(public.canonical_ranking_reward_payload()#>array['progression',p_category])
      with ordinality entry(value,ordinality)
    where p_rank_position between (entry.value->>0)::integer and (entry.value->>1)::integer
  loop
    v_reward_id := v_entry.value->>2;
    v_quantity := (v_entry.value->>3)::integer;
    v_reward_key := concat_ws(':',v_entry.value->>0,v_entry.value->>1,v_reward_id,v_entry.ordinality);
    v_item_id := public.resolve_canonical_reward_item(v_reward_id);

    insert into public.ranking_season_reward_grants(
      season_id,ranking_category,recipient_user_id,ranked_entity_id,rank_position,
      reward_key,master_reward_id,resolved_item_id,quantity
    ) values (
      p_season_id,p_category,p_recipient_user_id,p_ranked_entity_id,p_rank_position,
      v_reward_key,v_reward_id,v_item_id,v_quantity
    ) on conflict do nothing;

    if found then
      insert into public.presents(user_id,item_id,quantity,message,status,expire_at)
      values(p_recipient_user_id,v_item_id,v_quantity,v_message,'UNCLAIMED',clock_timestamp()+interval '30 days')
      returning id into v_present_id;
      update public.ranking_season_reward_grants set present_id=v_present_id
      where season_id=p_season_id and ranking_category=p_category
        and recipient_user_id=p_recipient_user_id and reward_key=v_reward_key;
      v_granted := v_granted + 1;
    end if;
  end loop;
  return v_granted;
end;
$function$

CREATE OR REPLACE FUNCTION public.grant_present_payload(p_user_id uuid, p_item_id text, p_quantity integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF p_quantity <= 0 THEN RAISE EXCEPTION 'Invalid present quantity'; END IF;

  IF p_item_id = 'CASH' THEN
    UPDATE public.users SET cash = cash + p_quantity WHERE id = p_user_id;
  ELSIF p_item_id IN ('DIA', 'DIAMOND') THEN
    UPDATE public.users SET neon_diamonds = neon_diamonds + p_quantity WHERE id = p_user_id;
  ELSIF EXISTS (
    SELECT 1 FROM public.equipment_battle_master WHERE equipment_id = p_item_id
  ) THEN
    INSERT INTO public.user_equipments (
      user_id, equipment_id, equipment_master_id, level, plus_val
    )
    SELECT p_user_id, p_item_id, p_item_id, 1, 0
    FROM generate_series(1, p_quantity);
  ELSE
    INSERT INTO public.user_items (user_id, item_id, quantity)
    VALUES (p_user_id, p_item_id, p_quantity)
    ON CONFLICT (user_id, item_id) DO UPDATE
    SET quantity = public.user_items.quantity + EXCLUDED.quantity;
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.grant_raid_reward(p_instance_id uuid, p_user_id uuid, p_reward_id integer, p_reason text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_reward record;
begin
  insert into public.raid_reward_grants(raid_boss_instance_id,user_id,reward_id,reward_reason)
  values(p_instance_id,p_user_id,p_reward_id,p_reason) on conflict do nothing;
  if not found then return false; end if;
  select coalesce(reward_item_id,item_id) item_id, greatest(coalesce(reward_quantity,quantity,1),1) quantity
  into v_reward from public.raid_rewards_master where id=p_reward_id;
  insert into public.presents(user_id,item_id,quantity,message,status,expire_at)
  values(p_user_id,v_reward.item_id,v_reward.quantity,'レイド報酬','UNCLAIMED',now()+interval '30 days');
  return true;
end; $function$

CREATE OR REPLACE FUNCTION public.guard_daily_profile_changes()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_today DATE := (now() AT TIME ZONE 'Asia/Tokyo')::DATE;
BEGIN
  IF NEW.username IS DISTINCT FROM OLD.username THEN
    IF char_length(btrim(NEW.username)) = 0 OR char_length(NEW.username) > 8 THEN
      RAISE EXCEPTION 'Username must be between 1 and 8 characters';
    END IF;
    IF OLD.last_username_changed_on = v_today THEN RAISE EXCEPTION 'Username can only be changed once per day'; END IF;
    NEW.last_username_changed_on := v_today;
  END IF;
  IF NEW.bio IS DISTINCT FROM OLD.bio THEN
    IF char_length(COALESCE(NEW.bio, '')) > 200 THEN RAISE EXCEPTION 'Bio must be 200 characters or fewer'; END IF;
    IF OLD.last_bio_changed_on = v_today THEN RAISE EXCEPTION 'Bio can only be changed once per day'; END IF;
    NEW.last_bio_changed_on := v_today;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_equipped_title_ownership()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.title_equipped IS NULL THEN
    RETURN NEW;
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_titles AS owned
    WHERE owned.user_id = NEW.id
      AND owned.title_id = NEW.title_equipped
  ) THEN
    RAISE EXCEPTION 'Equipped title must be owned by the user';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_gvg_membership_lock()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_guild_ids UUID[];
BEGIN
  v_guild_ids := ARRAY_REMOVE(ARRAY[
    CASE WHEN TG_OP <> 'INSERT' THEN OLD.guild_id ELSE NULL END,
    CASE WHEN TG_OP <> 'DELETE' THEN NEW.guild_id ELSE NULL END
  ], NULL);
  IF EXISTS (
    SELECT 1 FROM public.gvg_match_sessions match
    WHERE match.status = 'ACTIVE'
      AND now() >= match.scheduled_start_at AND now() < match.scheduled_end_at
      AND (match.guild_a_id = ANY(v_guild_ids) OR match.guild_b_id = ANY(v_guild_ids))
  ) THEN
    RAISE EXCEPTION 'Guild membership and roles are locked during active GvG';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_preopen_guild_power_cutoff()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_season_id uuid;
  v_starts_at timestamptz;
  v_ends_at timestamptz;
  v_status text;
  v_finalized boolean;
begin
  select season.id,season.starts_at,season.ends_at,season.status,
    exists(select 1 from public.ranking_guild_power_finalization_audits audit
           where audit.season_id=season.id)
  into strict v_season_id,v_starts_at,v_ends_at,v_status,v_finalized
  from public.ranking_guild_power_season_master master
  join public.ranking_seasons season on season.id=master.season_id
  where master.event_key='PREOPEN_GUILD_POWER_2026';

  if clock_timestamp()<v_starts_at then
    return null;
  end if;
  if v_status='PREPARING' then
    perform public.activate_preopen_guild_power_season();
  end if;
  if v_finalized then
    return null;
  elsif clock_timestamp()>=v_ends_at then
    perform public.finalize_preopen_guild_power_season();
  else
    -- Pre-cutoff work is admitted by season-row/share then advisory/share.
    -- The finalizer uses the same order with exclusive modes and waits for it.
    perform 1 from public.ranking_seasons where id=v_season_id for share;
    -- A transaction admitted before cutoff holds a shared lock through commit.
    -- The finalizer's exclusive lock therefore waits for all admitted writes.
    perform pg_advisory_xact_lock_shared(hashtextextended('PREOPEN_GUILD_POWER_2026',0));
  end if;
  return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.initialize_new_user(p_user_id uuid, p_username text, p_character_id text, p_area_id text, p_gift_code text DEFAULT NULL::text, p_gender text DEFAULT NULL::text, p_hair_id text DEFAULT NULL::text, p_face_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.uid() IS NULL OR auth.uid() <> p_user_id THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;
  IF char_length(trim(p_username)) NOT BETWEEN 1 AND 8 THEN
    RAISE EXCEPTION 'Username must contain 1 to 8 characters';
  END IF;
  IF EXISTS (SELECT 1 FROM public.users WHERE username = trim(p_username) AND id <> p_user_id) THEN
    RAISE EXCEPTION 'Username is already in use';
  END IF;

  INSERT INTO public.users (
    id, username, current_base_id, favorite_character_id, gift_code
  ) VALUES (
    p_user_id, trim(p_username), COALESCE(NULLIF(p_area_id, ''), 'neon_tower'),
    COALESCE(NULLIF(p_character_id, ''), '11111111-1111-1111-1111-111111111111'),
    NULLIF(trim(COALESCE(p_gift_code, '')), '')
  ) ON CONFLICT (id) DO NOTHING;

  INSERT INTO public.user_characters (user_id, character_id, level, awakening_level)
  VALUES (
    p_user_id,
    COALESCE(NULLIF(p_character_id, ''), '11111111-1111-1111-1111-111111111111'),
    1,
    0
  ) ON CONFLICT (user_id, character_id) DO NOTHING;

  RETURN jsonb_build_object('status', 'success');
END;
$function$

CREATE OR REPLACE FUNCTION public.issue_kpi_mypage_ready_context_v1(p_tutorial_version text, p_idempotency_key text, p_source text DEFAULT 'mypage_handshake_v1'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_subject uuid := public.kpi_v249_current_subject(); v_user uuid := auth.uid();
  v_context public.kpi_tutorial_mypage_ready_contexts%rowtype; v_leader text;
  v_step text; v_completed timestamptz; v_guild uuid; v_profile_guild uuid; v_member_count int;
begin
  if p_tutorial_version is null or p_tutorial_version !~ '^[A-Za-z0-9_.-]{1,64}$'
     or p_idempotency_key is null or p_idempotency_key !~ '^[A-Za-z0-9_.:-]{1,128}$'
     or p_source not in ('mypage_handshake_v1','qa_v1') then
    raise exception 'Invalid My Page context request' using errcode='22023'; end if;
  perform pg_advisory_xact_lock(hashtextextended('kpi249:mypage:'||v_subject||':'||p_idempotency_key,0));
  select * into v_context from public.kpi_tutorial_mypage_ready_contexts
    where subject_id=v_subject and idempotency_key=p_idempotency_key;
  if found then
    if v_context.tutorial_version is distinct from p_tutorial_version or v_context.source is distinct from p_source then
      raise exception 'Conflicting My Page context retry' using errcode='23505'; end if;
    return jsonb_build_object('context_id',v_context.context_id,'expires_at',v_context.expires_at,
      'profile_ready',v_context.profile_ready,'onboarding_ready',v_context.onboarding_ready,
      'identity_leader_ready',v_context.identity_leader_ready,
      'guild_membership_resolved',v_context.guild_membership_resolved,
      'guild_membership_status',v_context.guild_membership_status);
  end if;
  select favorite_character_id,guild_id into v_leader,v_profile_guild from public.users
    where id=v_user and nullif(btrim(username),'') is not null;
  if not found then raise exception 'Profile is not ready' using errcode='23514'; end if;
  select step_id,completed_at into v_step,v_completed from public.tutorial_progress where user_id=v_user;
  if v_step not in ('COMPLETE','AUTHENTICATION') or v_completed is null then
    raise exception 'Onboarding is not ready' using errcode='23514'; end if;
  if v_leader is null or not exists(select 1 from public.user_characters where user_id=v_user and character_id=v_leader) then
    raise exception 'Identity leader is not ready' using errcode='23514'; end if;
  select count(*),(array_agg(guild_id))[1] into v_member_count,v_guild from public.guild_members where user_id=v_user;
  if v_member_count > 1 or (v_member_count=1 and (v_profile_guild is distinct from v_guild
       or not exists(select 1 from public.guilds where id=v_guild and not is_disbanded)))
     or (v_member_count=0 and v_profile_guild is not null) then
    raise exception 'Guild membership is inconsistent' using errcode='23514'; end if;
  insert into public.kpi_tutorial_mypage_ready_contexts(subject_id,expires_at,profile_ready,onboarding_ready,
    identity_leader_ready,guild_membership_resolved,guild_membership_status,tutorial_version,source,idempotency_key)
  values(v_subject,clock_timestamp()+interval '10 minutes',true,true,true,true,
    case when v_member_count=1 then 'MEMBER' else 'NOT_MEMBER' end,p_tutorial_version,p_source,p_idempotency_key)
  returning * into v_context;
  return jsonb_build_object('context_id',v_context.context_id,'expires_at',v_context.expires_at,
    'profile_ready',true,'onboarding_ready',true,'identity_leader_ready',true,
    'guild_membership_resolved',true,'guild_membership_status',v_context.guild_membership_status);
end;
$function$

CREATE OR REPLACE FUNCTION public.join_guild(p_guild_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_mode text;
  v_cap integer;
  v_count integer;
  v_user public.users%rowtype;
begin
  if auth.uid() is null then raise exception 'Authentication is required'; end if;
  select * into v_user from public.users where id = auth.uid() for update;
  if not found then raise exception 'Guild joining requirements are not met'; end if;
  if v_user.last_guild_left_at is not null and v_user.last_guild_left_at > now() - interval '24 hours' then
    raise exception 'Guild rejoin cooldown is active'
      using errcode = 'P0001', detail = 'GUILD_JOIN_COOLDOWN_ACTIVE';
  end if;
  if exists(select 1 from public.guild_members where user_id = auth.uid()) then raise exception 'Already in a guild'; end if;
  select recruitment_mode, public.canonical_guild_member_cap(id)
    into v_mode, v_cap
  from public.guilds
  where id = p_guild_id and not is_disbanded
  for update;
  if not found then raise exception 'Guild not found'; end if;
  if v_mode <> 'OPEN_JOIN' then raise exception 'Guild does not accept direct joins'; end if;
  select count(*) into v_count from public.guild_members where guild_id = p_guild_id;
  if v_count >= v_cap then raise exception 'Guild member cap reached'; end if;
  insert into public.guild_members(guild_id, user_id, role, weekly_contribution, total_contribution)
  values(p_guild_id, auth.uid(), 'MEMBER', 0, 0);
  update public.guild_join_requests
  set status = 'CANCELLED', reviewed_at = now(), reviewed_by = auth.uid()
  where user_id = auth.uid() and status = 'PENDING';
  perform public.evaluate_mission_progress(auth.uid(), 'GUILD_JOIN', 1);
  return jsonb_build_object('status', 'success');
end;
$function$

CREATE OR REPLACE FUNCTION public.kpi_ensure_subject(p_user_id uuid, p_registered_at timestamp with time zone DEFAULT now(), p_registration_type text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
declare
  v_subject_id uuid;
  v_registration_type text := p_registration_type;
begin
  if p_user_id is null then
    raise exception 'p_user_id is required' using errcode = '22004';
  end if;

  select subject_id into v_subject_id
  from public.kpi_subjects
  where source_user_id = p_user_id;
  if v_subject_id is not null then
    return v_subject_id;
  end if;

  if v_registration_type is null then
    select case when au.is_anonymous then 'anonymous' else 'authenticated' end
    into v_registration_type
    from auth.users au
    where au.id = p_user_id;
  end if;
  v_registration_type := coalesce(v_registration_type, 'unknown');

  begin
    insert into public.kpi_subjects(source_user_id, registered_at, registration_type)
    values(p_user_id, coalesce(p_registered_at, now()), v_registration_type)
    returning subject_id into v_subject_id;
  exception when unique_violation then
    select subject_id into v_subject_id
    from public.kpi_subjects
    where source_user_id = p_user_id;
  end;

  return v_subject_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.kpi_record_daily_activity(p_user_id uuid, p_occurred_at timestamp with time zone DEFAULT clock_timestamp())
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_subject_id uuid;
  v_activity_date date;
begin
  v_subject_id := public.kpi_ensure_subject(p_user_id, p_occurred_at, null);
  v_activity_date := (p_occurred_at at time zone 'Asia/Tokyo')::date;

  insert into public.kpi_daily_user_activity(
    activity_date, subject_id, first_active_at, last_active_at, source
  ) values (
    v_activity_date, v_subject_id, p_occurred_at, p_occurred_at, 'sync_active_users'
  )
  on conflict (activity_date, subject_id) do update
  set first_active_at = least(public.kpi_daily_user_activity.first_active_at, excluded.first_active_at),
      last_active_at = greatest(public.kpi_daily_user_activity.last_active_at, excluded.last_active_at);
end;
$function$

CREATE OR REPLACE FUNCTION public.kpi_v249_current_subject()
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_subject uuid; v_user uuid := auth.uid(); v_session uuid;
begin
  if v_user is null or auth.jwt()->>'role' is distinct from 'authenticated' then
    raise exception 'Valid authenticated session required' using errcode = '42501';
  end if;
  begin v_session := (auth.jwt()->>'session_id')::uuid;
  exception when invalid_text_representation then
    raise exception 'Invalid session context' using errcode = '42501';
  end;
  if v_session is null or not exists (
    select 1 from auth.sessions where id = v_session and user_id = v_user
      and (not_after is null or not_after > clock_timestamp())
  ) then raise exception 'Session is not active' using errcode = '42501'; end if;
  select subject_id into v_subject from public.kpi_subjects
  where source_user_id = v_user and detached_at is null;
  if v_subject is null then
    raise exception 'Game Start subject does not exist' using errcode = '42501';
  end if;
  return v_subject;
end;
$function$

CREATE OR REPLACE FUNCTION public.leave_guild(p_user_id uuid, p_guild_id uuid, p_is_master boolean, p_has_others boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_role text;v_other integer;
begin if auth.uid() is null or auth.uid()<>p_user_id then raise exception 'Only current user can leave Guild'; end if;
 perform 1 from public.guilds where id=p_guild_id for update; select role into v_role from public.guild_members where guild_id=p_guild_id and user_id=auth.uid() for update;
 if v_role is null then raise exception 'Guild membership required'; end if; select count(*) into v_other from public.guild_members where guild_id=p_guild_id and user_id<>auth.uid();
 if v_role='MASTER' and v_other>0 then raise exception 'Transfer MASTER before leaving Guild'; end if;
 delete from public.guild_members where guild_id=p_guild_id and user_id=auth.uid(); update public.users set last_guild_left_at=now() where id=auth.uid();
 if v_role='MASTER' then update public.guilds set is_disbanded=true,disbanded_at=now(),recruitment_mode='CLOSED',approval_required=false where id=p_guild_id; end if;
 return jsonb_build_object('status','success','disbanded',v_role='MASTER'); end $function$

CREATE OR REPLACE FUNCTION public.normalize_user_mission_progress()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_target integer;
BEGIN
  SELECT target_value INTO v_target
  FROM public.missions
  WHERE id = NEW.mission_id;

  IF v_target IS NULL THEN
    RAISE EXCEPTION 'Mission master not found';
  END IF;

  NEW.current_progress := LEAST(GREATEST(COALESCE(NEW.current_progress, 0), 0), v_target);
  NEW.progress_val := NEW.current_progress;
  IF NEW.status = 'PROGRESS' AND NEW.current_progress >= v_target THEN
    NEW.status := 'CLEAR';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.on_canonical_daily_activity_finalized()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_day date:=(new.finalized_at at time zone 'Asia/Tokyo')::date; v_count integer; v_consumed integer; v_key text;
begin
 if old.finalization_status='FINALIZED' or new.finalization_status<>'FINALIZED' then return new; end if;
 if new.battle_mode='PVP' then
  v_key:='PVP_BATTLE:'||new.id::text;
  insert into public.canonical_daily_activity_claims values(v_day,new.requester_user_id,v_key,new.id,'[{"itemId":"CHAR_EXP_S","quantity":1}]',now()) on conflict do nothing;
  if found then insert into public.presents(user_id,item_id,quantity,message,status,expire_at) values(new.requester_user_id,'CHAR_EXP_S',1,'PvPバトル報酬','UNCLAIMED',now()+interval '30 days'); end if;
  select count(*) into v_count from public.battle_replay_sessions where requester_user_id=new.requester_user_id and battle_mode='PVP' and finalization_status='FINALIZED' and (finalized_at at time zone 'Asia/Tokyo')::date=v_day;
  if v_count>=3 then
   insert into public.canonical_daily_activity_claims values(v_day,new.requester_user_id,'PVP_DAILY_3',new.id,'[{"itemId":"SKILL_MANUAL","quantity":1},{"itemId":"CASH","quantity":40}]',now()) on conflict do nothing;
   if found then insert into public.presents(user_id,item_id,quantity,message,status,expire_at) values(new.requester_user_id,'SKILL_MANUAL',1,'PvPデイリー報酬','UNCLAIMED',now()+interval '30 days'),(new.requester_user_id,'CASH',40,'PvPデイリー報酬','UNCLAIMED',now()+interval '30 days'); end if;
  end if;
 elsif new.battle_mode='RAID' then
  v_key:='RAID_BATTLE:'||new.id::text;
  insert into public.canonical_daily_activity_claims values(v_day,new.requester_user_id,v_key,new.id,'[{"itemId":"EQUIP_EXP_S","quantity":1}]',now()) on conflict do nothing;
  if found then insert into public.presents(user_id,item_id,quantity,message,status,expire_at) values(new.requester_user_id,'EQUIP_EXP_S',1,'レイドバトル報酬','UNCLAIMED',now()+interval '30 days'); end if;
  select count(*) into v_count from public.battle_replay_sessions where requester_user_id=new.requester_user_id and battle_mode='RAID' and finalization_status='FINALIZED' and (finalized_at at time zone 'Asia/Tokyo')::date=v_day;
  if v_count>=3 then
   insert into public.canonical_daily_activity_claims values(v_day,new.requester_user_id,'RAID_DAILY_3',new.id,'[{"itemId":"CHAR_EXP_M","quantity":1},{"itemId":"CASH","quantity":40}]',now()) on conflict do nothing;
   if found then insert into public.presents(user_id,item_id,quantity,message,status,expire_at) values(new.requester_user_id,'CHAR_EXP_M',1,'レイドデイリー報酬','UNCLAIMED',now()+interval '30 days'),(new.requester_user_id,'CASH',40,'レイドデイリー報酬','UNCLAIMED',now()+interval '30 days'); end if;
  end if;
  select coalesce(sum(progress.raid_points_consumed),0) into v_consumed from public.raid_instance_user_progress progress join public.raid_bosses boss on boss.id=progress.raid_boss_instance_id where progress.user_id=new.requester_user_id and boss.raid_day_key=v_day::text;
  if v_consumed>=5 then
   insert into public.canonical_daily_activity_claims values(v_day,new.requester_user_id,'RAID_POINTS_5',new.id,'[{"itemId":"EQUIP_LB_PART","quantity":1}]',now()) on conflict do nothing;
   if found then insert into public.presents(user_id,item_id,quantity,message,status,expire_at) values(new.requester_user_id,'EQUIP_LB_PART',1,'レイド参加報酬','UNCLAIMED',now()+interval '30 days'); end if;
  end if;
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.on_daily_mission_authority_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_mission public.missions%rowtype;
begin
  -- Rollover resets CLEAR/CLAIMED rows to PROGRESS in one statement. Ignore
  -- those reverse transitions so this row trigger never updates another row
  -- that the same statement is still scheduled to update.
  if old.status is not distinct from new.status
    or new.status not in ('CLEAR', 'CLAIMED') then
    return new;
  end if;
  select * into v_mission from public.missions where id = new.mission_id;
  if not found
    or not v_mission.is_enabled
    or v_mission.category <> 'DAILY'
    or v_mission.trigger_type = 'DAILY_MISSION_COMPLETED_COUNT'
    or new.cycle_date is null then
    return new;
  end if;
  perform public.refresh_daily_mission_completion_aggregates(new.user_id, new.cycle_date);
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.on_kpi_auth_method_created()
