CREATE OR REPLACE FUNCTION public.refresh_kpi_snapshots(p_category text, p_period_type text, p_period_start date, p_period_end date, p_requested_by uuid DEFAULT auth.uid())
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_run_id uuid;
  v_watermark timestamptz := clock_timestamp();
  v_error_state text;
  v_error_message text;
begin
  if p_category not in ('acquisition', 'active_retention', 'guild', 'content', 'revenue') then raise exception 'unsupported KPI category'; end if;
  if p_period_type not in ('daily', 'monthly', 'cohort') then raise exception 'unsupported KPI period type'; end if;
  if p_period_end <= p_period_start or p_period_end > p_period_start + 31 then raise exception 'KPI period must contain between 1 and 31 days'; end if;

  insert into public.kpi_aggregation_runs(
    category, period_type, period_start, period_end, status, requested_by,
    aggregation_version, exclusion_rule_version, source_watermark
  ) values (
    p_category, p_period_type, p_period_start, p_period_end, 'pending', p_requested_by,
    'p0-v2-timeseries', 'period-classification-v1', v_watermark
  ) returning run_id into v_run_id;

  begin
    if not pg_try_advisory_xact_lock(hashtextextended(concat_ws(':', p_category, p_period_type, p_period_start, p_period_end), 0)) then
      raise exception 'KPI refresh already running for this category and period';
    end if;
    perform set_config('statement_timeout', '15000', true);
    update public.kpi_aggregation_runs set status = 'running', started_at = clock_timestamp() where run_id = v_run_id;

    case p_category
      when 'acquisition' then perform public.refresh_kpi_acquisition_v2(v_run_id, p_period_type, p_period_start, p_period_end, v_watermark);
      when 'active_retention' then
        if p_period_type = 'cohort' then
          perform public.refresh_kpi_active_retention(v_run_id, p_period_type, p_period_start, p_period_end, v_watermark);
        else
          perform public.refresh_kpi_active_timeseries_v2(v_run_id, p_period_type, p_period_start, p_period_end, v_watermark);
        end if;
      when 'guild' then perform public.refresh_kpi_guild_timeseries_v2(v_run_id, p_period_type, p_period_start, p_period_end, v_watermark);
      when 'content' then perform public.refresh_kpi_content(v_run_id, p_period_type, p_period_start, p_period_end, v_watermark);
      when 'revenue' then perform public.refresh_kpi_revenue(v_run_id, p_period_type, p_period_start, p_period_end);
    end case;

    update public.kpi_aggregation_runs set status = 'succeeded', finished_at = clock_timestamp() where run_id = v_run_id;
  exception when query_canceled then
    delete from public.kpi_metric_snapshots where run_id = v_run_id;
    update public.kpi_aggregation_runs set status='failed', finished_at=clock_timestamp(), error_code='57014', error_detail='KPI refresh exceeded statement timeout' where run_id=v_run_id;
  when others then
    get stacked diagnostics v_error_state = returned_sqlstate, v_error_message = message_text;
    delete from public.kpi_metric_snapshots where run_id = v_run_id;
    update public.kpi_aggregation_runs set status='failed', finished_at=clock_timestamp(), error_code=v_error_state, error_detail=left(v_error_message,2000) where run_id=v_run_id;
  end;
  return v_run_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.refresh_user_power_projection(p_user_id uuid)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_power bigint; v_day date:=(clock_timestamp() at time zone 'Asia/Tokyo')::date;
begin
  if p_user_id is null then return 0; end if;
  if not exists(select 1 from public.users where id=p_user_id) then
    delete from public.user_power_rankings where user_id=p_user_id;
    return 0;
  end if;
  v_power:=public.calculate_user_total_power(p_user_id);
  insert into public.user_power_rankings(user_id,total_power,updated_at)
  values(p_user_id,least(v_power,2147483647)::integer,clock_timestamp())
  on conflict(user_id) do update set total_power=excluded.total_power,updated_at=excluded.updated_at;
  update public.ranking_daily_activity_snapshots set total_power=v_power,last_active_at=clock_timestamp()
  where ranking_day_key=v_day and user_id=p_user_id;
  return v_power;
end;
$function$

CREATE OR REPLACE FUNCTION public.reject_guild_power_snapshot_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if tg_op='INSERT' then
    if exists(
      select 1 from public.ranking_guild_power_finalization_audits audit
      where audit.season_id=new.season_id
    ) then
      raise exception 'final guild Power snapshot is immutable' using errcode='55000';
    end if;
    return new;
  end if;
  raise exception 'final guild Power snapshot is immutable' using errcode='55000';
end;
$function$

CREATE OR REPLACE FUNCTION public.remove_legacy_pvp_cash_before_finalize()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_legacy_cash integer;
begin
 if old.finalization_status<>'FINALIZED' and new.finalization_status='FINALIZED' and new.battle_mode='PVP' then
  v_legacy_cash:=greatest(coalesce((new.finalization_result#>>'{rewards,cash}')::integer,0),0);
  if v_legacy_cash>0 then update public.users set cash=cash-v_legacy_cash where id=new.requester_user_id; end if;
  new.finalization_result:=jsonb_set(new.finalization_result,'{rewards,cash}','0'::jsonb,true);
  new.result:=jsonb_set(new.result,'{rewards,cash}','0'::jsonb,true);
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.resolve_canonical_reward_item(p_reward_id text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_roll integer:=floor(random()*3)::integer;
begin
 if p_reward_id='NORMAL_GACHA_TICKET_RANDOM' then return (array['NORMAL_GACHA_TICKET_CHARACTER','NORMAL_GACHA_TICKET_SKILL','NORMAL_GACHA_TICKET_EQUIPMENT'])[v_roll+1]; end if;
 if p_reward_id='SPECIAL_TICKET_RANDOM' then return (array['SPECIAL_TICKET_CHARACTER','SPECIAL_TICKET_SKILL','SPECIAL_TICKET_EQUIPMENT'])[v_roll+1]; end if;
 if p_reward_id='SPECIAL_TICKET_SKILL_OR_EQUIPMENT' then return (array['SPECIAL_TICKET_SKILL','SPECIAL_TICKET_EQUIPMENT'])[floor(random()*2)::integer+1]; end if;
 return p_reward_id;
end $function$

CREATE OR REPLACE FUNCTION public.respawn_cleared_raid_slot(p_cleared_instance_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_old public.raid_bosses%rowtype; v_new uuid;
begin
 perform pg_advisory_xact_lock(hashtextextended(p_cleared_instance_id::text||':respawn',0));
 select * into v_old from public.raid_bosses where id=p_cleared_instance_id and status='CLEARED' and respawn_after<=now() for update;
 if not found then return null; end if;
 if exists(select 1 from public.raid_bosses where raid_day_key=v_old.raid_day_key and base_id=v_old.base_id and status='ACTIVE') then return null; end if;
 insert into public.raid_bosses(boss_id,boss_master_id,current_hp,max_hp,base_id,status,spawned_at,expires_at,cycle_id,rotation_date,raid_variant_id,raid_day_key)
 values(v_old.boss_id,v_old.boss_master_id,v_old.max_hp,v_old.max_hp,v_old.base_id,'ACTIVE',now(),v_old.expires_at,gen_random_uuid(),v_old.rotation_date,v_old.raid_variant_id,v_old.raid_day_key) returning id into v_new;
 return v_new;
end $function$

CREATE OR REPLACE FUNCTION public.rotate_daily_raids()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_today date:=(clock_timestamp() at time zone 'Asia/Tokyo')::date; v_pair text[]; v_area text; v_variant public.canonical_raid_variants%rowtype; v_start timestamptz; v_end timestamptz; v_cleared record;
begin
 perform pg_advisory_xact_lock(hashtextextended('CANONICAL_RAID_ROTATION:'||v_today::text,0));
 for v_cleared in select id from public.raid_bosses where status='ACTIVE' and (current_hp=0 or expires_at<=now()) for update loop perform public.finalize_expired_raid_instance(v_cleared.id); end loop;
 for v_cleared in select id from public.raid_bosses where status='CLEARED' and raid_day_key=v_today::text and respawn_after<=now() for update loop perform public.respawn_cleared_raid_slot(v_cleared.id); end loop;
 v_pair:=public.canonical_raid_rotation_pair(v_today); v_start:=(v_today::timestamp at time zone 'Asia/Tokyo'); v_end:=v_start+interval '24 hours';
 foreach v_area in array v_pair loop
  if not exists(select 1 from public.raid_bosses where raid_day_key=v_today::text and base_id=v_area and status='ACTIVE') and not exists(select 1 from public.raid_bosses where raid_day_key=v_today::text and base_id=v_area and status='CLEARED' and respawn_after>now()) then
   select * into v_variant from public.canonical_raid_variants where area_id=upper(v_area) and is_production_enabled order by raid_variant_id limit 1;
   insert into public.raid_bosses(boss_id,boss_master_id,current_hp,max_hp,base_id,status,spawned_at,expires_at,cycle_id,rotation_date,raid_variant_id,raid_day_key) values(v_variant.raid_variant_id,v_variant.raid_variant_id,v_variant.max_hp,v_variant.max_hp,v_area,'ACTIVE',greatest(now(),v_start),v_end,gen_random_uuid(),v_today,v_variant.raid_variant_id,v_today::text);
  end if;
 end loop;
end $function$

CREATE OR REPLACE FUNCTION public.start_raid_battle(p_instance_id uuid, p_character_ids text[], p_tactic text DEFAULT 'ATTACK_PRIORITY'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_uid uuid:=auth.uid(); v_user public.users%rowtype; v_instance record; v_cost integer; v_cost_type text; v_guild uuid; v_players jsonb; v_enemy jsonb:='[]'; v_member text; v_entry record; v_skill_refs jsonb; v_skills jsonb; v_replay uuid; v_seed bigint; v_slot integer:=0;
begin
 if v_uid is null then raise exception 'authentication required' using errcode='42501'; end if;
 if p_tactic not in('ATTACK_PRIORITY','HEAL_PRIORITY','SKILL_PRIORITY','BALANCED','WEAKNESS_FOCUS') then raise exception 'invalid tactic' using errcode='22023'; end if;
 perform public.sync_and_recover_vitality_and_pvp_points(v_uid); select * into v_user from public.users where id=v_uid for update;
 if v_user.level<5 then raise exception 'player level 5 is required' using errcode='23514'; end if;
 select boss.*,variant.raid_name,variant.atk,variant.def,variant.spd,variant.member_character_ids into v_instance from public.raid_bosses boss join public.canonical_raid_variants variant on variant.raid_variant_id=boss.raid_variant_id where boss.id=p_instance_id and boss.status='ACTIVE' and boss.expires_at>now() for update of boss;
 if not found then raise exception 'Raid instance is not active' using errcode='P0002'; end if;
 if not v_user.raid_free_entry_consumed then v_cost:=0;v_cost_type:='FREE_FIRST';update public.users set raid_free_entry_consumed=true where id=v_uid;
 elsif v_user.raid_points>=1 then v_cost:=1;v_cost_type:='RAID_POINT';update public.users set raid_points=raid_points-1,raid_points_last_recovered_at=case when raid_points=5 then now() else raid_points_last_recovered_at end where id=v_uid;v_user.raid_points:=v_user.raid_points-1;
 else raise exception 'insufficient Raid points' using errcode='23514'; end if;
 select guild_id into v_guild from public.guild_members where user_id=v_uid; v_players:=public.build_server_battle_snapshot(v_uid,p_character_ids,'PLAYER');
 for v_member in select value from jsonb_array_elements_text(v_instance.member_character_ids) loop
  v_slot:=v_slot+1; select * into v_entry from public.canonical_quest_enemy_pool_entries where version='2026-08-30' and character_id=v_member and difficulty='HARD' order by(local_affinity)desc,weight desc limit 1;
  v_skill_refs:=coalesce(v_entry.skill_loadout,(select jsonb_agg(skill_id order by skill_id) from(select skill_id from public.canonical_skill_master where version='2026-08-21' and exclusive_character_id=v_member order by skill_id limit 2)s),(select jsonb_agg(skill_id order by skill_id) from(select skill_id from public.canonical_skill_master where version='2026-08-21' and exclusive_character_id is null order by skill_id limit 2)s),'[]'::jsonb);
  select coalesce(jsonb_agg(jsonb_build_object('id',s.skill_id,'name',s.display_name,'activationType',s.activation_type,'cooldown',s.cooldown,'availableFromRound',s.available_from_round,'target',s.target,'effects',s.effects,'exclusiveCharacterId',s.exclusive_character_id) order by x.ordinality),'[]') into v_skills from jsonb_array_elements_text(v_skill_refs) with ordinality x(skill_id,ordinality) join public.canonical_skill_master s on s.version='2026-08-21' and s.skill_id=x.skill_id;
  v_enemy:=v_enemy||jsonb_build_array(jsonb_build_object('id','raid_'||v_instance.id||'_'||v_slot,'characterId',v_member,'name',coalesce((select display_name from public.canonical_character_master where version='2026-08-21' and character_id=v_member),v_member),'team','ENEMY','alignment',coalesce((select attribute from public.canonical_character_master where version='2026-08-21' and character_id=v_member),'NEUTRAL'),'level',30,'stats',jsonb_build_object('hp',ceil(v_instance.max_hp::numeric/5),'atk',v_instance.atk,'def',v_instance.def,'spd',v_instance.spd,'luk',0),'equippedSkillRefs',v_skill_refs,'skills',v_skills,'equipment','[]'::jsonb));
 end loop;
 v_seed:=floor(random()*2147483646)::bigint+1;
 insert into public.battle_replay_sessions(requester_user_id,battle_mode,source_reference_id,tactic_id,random_seed,player_snapshot,enemy_snapshot,resolution_authority,finalization_status,official_context) values(v_uid,'RAID',p_instance_id,p_tactic,v_seed,v_players,v_enemy,'RAID_SERVER','PENDING',jsonb_build_object('guildIdSnapshot',v_guild,'costType',v_cost_type,'cost',v_cost,'remainingRaidPoints',v_user.raid_points,'bossHpAtStart',v_instance.current_hp,'bossMaxHp',v_instance.max_hp,'baseId',v_instance.base_id,'raidDayKey',v_instance.raid_day_key,'raidVariantId',v_instance.raid_variant_id)) returning id into v_replay;
 return jsonb_build_object('replay_session_id',v_replay,'player_snapshot',v_players,'enemy_snapshot',v_enemy,'cost_type',v_cost_type,'cost',v_cost,'remaining_raid_points',v_user.raid_points,'guild_id_snapshot',v_guild);
end $function$

CREATE OR REPLACE FUNCTION public.sync_and_recover_vitality_and_pvp_points(p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_user public.users%rowtype; v_now timestamptz:=now(); v_vit_steps integer; v_pvp_steps integer; v_raid_steps integer;
 v_vit integer; v_pvp integer; v_raid integer; v_vit_at timestamptz; v_pvp_at timestamptz; v_raid_at timestamptz;
begin
 if auth.uid() is null or auth.uid()<>p_user_id then raise exception 'not authorized' using errcode='42501'; end if;
 select * into v_user from public.users where id=p_user_id for update;
 if not found then raise exception 'user not found' using errcode='P0002'; end if;
 v_vit:=least(500,greatest(0,v_user.vitality)); v_pvp:=least(5,greatest(0,v_user.pvp_points)); v_raid:=least(5,greatest(0,v_user.raid_points));
 v_vit_at:=v_user.vitality_last_recovered_at; v_pvp_at:=v_user.pvp_points_last_recovered_at; v_raid_at:=v_user.raid_points_last_recovered_at;
 if v_vit<100 then
  v_vit_steps:=greatest(0,floor(extract(epoch from(v_now-coalesce(v_vit_at,v_now)))/360));
  v_vit:=least(100,v_vit+v_vit_steps);
  if v_vit_steps>0 then v_vit_at:=case when v_vit=100 then v_now else v_vit_at+(v_vit_steps*interval '360 seconds') end; end if;
 end if;
 if v_pvp<5 then
  v_pvp_steps:=greatest(0,floor(extract(epoch from(v_now-coalesce(v_pvp_at,v_now)))/7200));
  v_pvp:=least(5,v_pvp+v_pvp_steps);
  if v_pvp_steps>0 then v_pvp_at:=case when v_pvp=5 then v_now else v_pvp_at+(v_pvp_steps*interval '7200 seconds') end; end if;
 end if;
 if v_raid<5 then
  v_raid_steps:=greatest(0,floor(extract(epoch from(v_now-coalesce(v_raid_at,v_now)))/7200));
  v_raid:=least(5,v_raid+v_raid_steps);
  if v_raid_steps>0 then v_raid_at:=case when v_raid=5 then v_now else v_raid_at+(v_raid_steps*interval '7200 seconds') end; end if;
 end if;
 update public.users set vitality=v_vit,vitality_last_recovered_at=v_vit_at,pvp_points=v_pvp,pvp_points_last_recovered_at=v_pvp_at,
  raid_points=v_raid,raid_points_last_recovered_at=v_raid_at where id=p_user_id;
 return jsonb_build_object('out_vitality',v_vit,'out_pvp_points',v_pvp,'out_raid_points',v_raid,
  'out_cash',v_user.cash,'out_diamonds',v_user.neon_diamonds,'raid_first_entry_free',not v_user.raid_free_entry_consumed,
  'vitality_next_recovery_at',case when v_vit<100 then v_vit_at+interval '360 seconds' else null end,
  'pvp_next_recovery_at',case when v_pvp<5 then v_pvp_at+interval '7200 seconds' else null end,
  'raid_next_recovery_at',case when v_raid<5 then v_raid_at+interval '7200 seconds' else null end);
end $function$

CREATE OR REPLACE FUNCTION public.sync_user_guild_membership()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    UPDATE public.users SET guild_id = NEW.guild_id WHERE id = NEW.user_id;
    RETURN NEW;
  END IF;
  UPDATE public.users SET guild_id = NULL WHERE id = OLD.user_id AND guild_id = OLD.guild_id;
  RETURN OLD;
END;
$function$
